* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 100%; height: 100%;
  background: transparent;
  display: flex; align-items: center; justify-content: center;
  font-family: system-ui, sans-serif;
}
.container {
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  padding: 10px 14px;
  gap: 6px;
}
.label {
  font-size: 9px; font-weight: 700;
  color: #6F8296; letter-spacing: 0.04em;
}
.bar-wrap {
  width: 100%; height: 22px;
  border-radius: 99px;
  border: 2px solid #6F8296;
  overflow: hidden;
  position: relative;
  background: #fff;
}
.bar-fill {
  position: absolute; top: 0; left: 0;
  height: 100%; width: 60%;
  border-radius: 99px;
  background: linear-gradient(to right, #fff 0%, #94A9BB  100%);
}
.bar-icons {
  position: absolute; top: 0; left: 0;
  width: 100%; height: 100%;
  display: flex; align-items: center;
  justify-content: space-around;
  padding: 0 10px;
  pointer-events: none;
}

/* 全局邊距重置 */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  width: 100%;
  height: 100%;
  background: transparent;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0 !important;
}

/* 主卡片容器：調整為高透圓角毛玻璃 */
.search-card {
  width: 100%;
  height: 52%;                      
  background: rgba(255, 255, 255, 0.4);  /* 核心修改：提高透明度，讓整體更通透 */
  backdrop-filter: blur(12px);       
  -webkit-backdrop-filter: blur(12px);
  border-radius: 18px !important;        /* 核心修改：加上精緻的圓角弧度 */
  box-shadow: none !important;        
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;                   
  overflow: hidden;
}

/* 中間搜尋文字區域 */
.search-main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;                          
  padding: 0 8px;
}

/* 搜尋提示文字 */
.search-text {
  font-family: -apple-system, "SF Pro Text", "PingFang SC", sans-serif;
  font-size: 11px;                 
  color: #222222;                    
  letter-spacing: 0.3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 中間放大鏡圖標 */
.search-hint-icon {
  width: 15px;                       
  height: 15px;
  fill: #1a1a1a;
  flex-shrink: 0;
}

/* 左右兩側功能圖標 */
.icon-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.icon-wrapper svg {
  width: 17px;                       
  height: 17px;
  fill: #222222;
}

/* 針對左側選單圖標進行微調 */
.left-icon svg {
  width: 16px;
  height: 16px;
}

/* 針對右側麥克風進行微調 */
.right-icon svg {
  width: 15px;
  height: 15px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 100%; height: 100%;
  background: transparent;
  font-family: system-ui, sans-serif;
}
.card {
  width: 100%; height: 100%;
  background: #fff;
  border-radius: 20px;
  display: flex; flex-direction: column;
  padding: 10px 10px 8px;
  gap: 7px;
  overflow: hidden;
}
.header {
  display: flex; align-items: center; gap: 7px; flex-shrink: 0;
}
.avatar {
  width: 28px; height: 28px; border-radius: 50%;
  background: #d4d2ce; flex-shrink: 0; overflow: hidden;
}
.avatar img { width: 100%; height: 100%; object-fit: cover; display: block; }
.header-info { flex: 1; min-width: 0; }
.username { font-size: 8px; font-weight: 700; color: #111; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.location { font-size: 6.5px; color: #888; display: flex; align-items: center; gap: 2px; margin-top: 1px; }
.more { flex-shrink: 0; display: flex; flex-direction: column; gap: 2px; padding: 2px; opacity: 0.5; }
.more span { width: 2.5px; height: 2.5px; border-radius: 50%; background: #333; display: block; }
.photo {
  flex: 1; min-height: 0;
  border-radius: 10px;
  background: #d4d2ce;
  overflow: hidden;
}
.photo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.stars-row {
  display: flex; align-items: center; gap: 5px; flex-shrink: 0;
}
.star { cursor: pointer; transition: transform 0.15s ease; }
.star:active { transform: scale(1.2); }
.star svg { display: block; }
.star-label { font-size: 6.5px; color: #555; margin-left: 2px; white-space: nowrap; }

/* ===== 卡片整体 ===== */
.wechat-moment-card {
  width: 100%;
  max-width: 380px;
  aspect-ratio: 1;
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 12px 28px rgba(0,0,0,0.15);
  display: flex;
  flex-direction: column;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI";
}

/* ===== 封面 ===== */
.cover-area {
  position: relative;
  height: 50%;
}
.cover-bg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 昵称（覆盖在封面上） */
.username {
  position: absolute;
  left: 160px;
  bottom: 10px;

  font-size: 20px;
  font-weight: 600;
  color: #fff;
  text-shadow: 0 2px 8px rgba(0,0,0,0.5);
}

/* ===== 内容区（半透明） ===== */
.content-area {
  position: relative;
  flex: 1;
  background: rgba(255,255,255,0.50);
  backdrop-filter: blur(6px);
  padding: 50px 16px 16px; /* 上方留给头像 */
}

/* ===== 头像（骑跨） ===== */
.avatar-box {
  position: absolute;
  right: 16px;
  top: -32px; /* 关键：跨在中间 */

  width: 64px;
  height: 64px;
  border-radius: 12px;
  overflow: hidden;
  border: 3px solid #fff;
  background: #ddd;
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ===== 文案 ===== */
.moment-text {
  font-size: 14px;
  color: #333;

  position: relative;
  left: 95px;
  top: 0px;
}

/* ===== 图片区域 ===== */
.image-section {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
}

.top-label {
  font-size: 12px;
  color: #666;
  background: #eee;
  padding: 4px 10px;
  border-radius: 20px;
}

/* 三图横排（固定） */
.image-row {
  display: flex;
  gap: 8px;
}

.image-row img {
  width: 70px;
  height: 70px;
  border-radius: 10px;
  object-fit: cover;
}

/*全局重置*/
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  width: 100%;
  height: 100%;
  background: transparent;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0 !important; /*外邊距*/
}

/*拍立得主卡片*/
.polaroid-card {
  width: 100%;
  height: 100%;
  background: #FFF7FA ;
  border-radius: 0px !important; /*直角*/
  box-shadow: none !important;    /*外陰影*/
  padding: 12px 12px 14px 12px;  /*內部留白*/
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/*照片區域*/
.photo-area {
  width: 100%;
  height: 58%; /* 調整照片高度比例 */
  background-color: #f0f0f0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border-radius: 0px !important; /*直角*/
  border: 1px solid #e5e5e5;
  position: relative;

  /*黑白質感（若不需要黑白，可刪除下面這行）*/
  filter: grayscale(100%) contrast(110%); 
}

/*上傳提示*/
.upload-tip {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 11px;
  color: #aaaaaa;
}
.photo-area[style*="url"] .upload-tip {
  display: none;
}

/*音樂控制區*/
.music-zone {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px; /*間距*/
  padding-top: 4px;
}

/*進度條*/
.progress-container {
  width: 100%;
  height: 2px;
  background: #e0e0e0;
  position: relative;
}

.progress-bar {
  width: 30%;
  height: 100%;
  background: #757575;
}

.progress-handle {
  width: 6px;
  height: 6px;
  background: #757575;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: 30%;
  transform: translate(-50%, -50%);
}

/*按鈕排版*/
.control-buttons {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 0 2px;
}

/*圖標按鈕*/
.icon-btn {
  background: none;
  border: none;
  outline: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icon-btn svg {
  width: 14px;
  height: 14px;
  fill: #6c6c6c;
}

/*播放按鈕*/
.play-circle {
  width: 28px;
  height: 28px;
  background: #5a5a5a;
  border: none;
  border-radius: 50%; /* 保持播放鈕為正圓 */
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.play-circle svg {
  width: 13px;
  height: 13px;
  fill: #ffffff;
  margin-left: 1px;
}

/*當播放按鈕切換為暫停圖標時，取消置中微調 */
.play-circle svg:has(path[d*='M6']) {
  margin-left: 0;
}

/*愛心點亮變紅*/
.icon-btn.active svg {
  fill: #ff4d4f;
}

/*點擊微小縮放回饋*/
.icon-btn:active, .play-circle:active {
  transform: scale(0.9);
}

