* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  font-family: 'Georgia', serif;
}

.widget {
  width: calc(100% - 24px);
  height: calc(100% - 24px);
  display: flex; flex-direction: column;
  background: transparent;
  border-radius: 12px;
  padding: 20px 18px;
  margin: 12px;
  border: 1.5px dashed #c8c0b8;
  position: relative;
  overflow: visible;
  box-sizing: border-box;
}

/* ── 八个角块，骑在虚线上 ── */
.corner {
  position: absolute;
  width: 8px; height: 8px;
  border: 1.5px solid #b0a898;
  background: transparent;
  pointer-events: none;
  z-index: 2;
}
.corner.tl { top: -4px;  left: -4px; }
.corner.tr { top: -4px;  right: -4px; }
.corner.bl { bottom: -4px; left: -4px; }
.corner.br { bottom: -4px; right: -4px; }
.corner.tm { top: -4px;    left: 50%; transform: translateX(-50%); }
.corner.bm { bottom: -4px; left: 50%; transform: translateX(-50%); }
.corner.ml { left: -4px;   top: 50%;  transform: translateY(-50%); }
.corner.mr { right: -4px;  top: 50%;  transform: translateY(-50%); }

/* ── 引用区 ── */
.quote-area {
  flex: 0 0 46%;
  display: flex; flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow: hidden;
}

.star-deco {
  display: flex; align-items: center; gap: 4px;
  color: #a09080;
  margin-bottom: 5px;
  justify-content: flex-start;
  width: 100%;
}
.star-icon  { width: 14px; height: 14px; }
.dot-icon   { width: 6px;  height: 6px; }
.cross-icon { width: 11px; height: 11px; }

.quote-text {
  font-size: 13px;
  font-style: italic;
  color: #2a2a2a;
  line-height: 1.65;
  letter-spacing: 0.2px;
  text-align: center;
  width: 100%;
}
.quote-text sup {
  font-size: 6px; color: #bbb; vertical-align: super;
}
.inline-cross {
  width: 9px; height: 9px;
  display: inline; vertical-align: middle;
  color: #a09080;
}

/* ── 分隔线 ── */
.divider {
  width: 100%; height: 1px;
  background: #e0d8d0;
  flex-shrink: 0;
  margin: 2px 0 4px;
}

/* ── 歌词区 ── */
.lyrics-area {
  flex: 1;
  display: flex; flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 4px;
  min-height: 0;
  overflow: hidden;
}
.lyric-line {
  font-size: 10px;
  color: #666;
  text-align: center;
  line-height: 1.6;
  letter-spacing: 0.2px;
  font-family: 'Georgia', serif;
  width: 100%;
}
.lyric-line:last-child {
  font-size: 8.5px;
  color: #aaa;
  margin-top: 2px;
  letter-spacing: 0.8px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: transparent;
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-family: -apple-system, 'SF Pro Text', 'Helvetica Neue', sans-serif;
}

.widget {
  display: flex; flex-direction: column;
  align-items: center;
  width: 100%;
  padding: 0 10px;
}

/* ── 菜单主体 ── */
.menu-bar {
  display: flex; align-items: center;
  background: rgba(255, 255, 255, 0.96);
  border-radius: 14px;
  box-shadow:
    0 8px 32px rgba(0,0,0,0.18),
    0 2px 8px rgba(0,0,0,0.10),
    0 0 0 0.5px rgba(0,0,0,0.08);
  padding: 0 4px;
  height: 46px;
  width: 100%;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

/* ── 分隔线 ── */
.sep {
  width: 0.5px;
  height: 28px;
  background: rgba(0,0,0,0.12);
  flex-shrink: 0;
}

/* ── 每个菜单项 ── */
.menu-item {
