}

/* ── 小尾巴 ── */
.tail {
  width: 14px; height: 8px;
  background: rgba(255,255,255,0.96);
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  margin-top: -1px;
  box-shadow: 0 4px 8px rgba(0,0,0,0.08);
}

body { margin: 0; padding: 0; box-sizing: border-box; height: 100%; width: 100%; }
.w-card {
  --c-main: #E8C8D0 ;
  --c-darker: #E8C8D0 ;
