:root {
  /* ==========================================
     我方气泡 (冰透蓝、无边框、缩小、方圆)
  ========================================== */
  --bubble-me-bg: #E1F6FF;               /* 变更为治愈冰透蓝 */
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #415A6B;            /* 文字适配为深海蓝灰 */
  --bubble-me-border: none;
  --bubble-me-shadow: 0 1px 3px rgba(162, 203, 227, 0.15);
  --bubble-me-link-color: #8AA3B3;       

  /* 1. 缩小整体与高度 */
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.35;
  --bubble-me-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-me-radius: 12px;
  --bubble-me-radius-first: 12px 12px 4px 12px;
  --bubble-me-radius-mid: 12px 4px 4px 12px;
  --bubble-me-radius-last: 12px 4px 12px 12px;

  /* ==========================================
     对方气泡 (白色、薄冰蓝边框、缩小、方圆)
  ========================================== */
  --bubble-them-bg: #FFFFFF;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #415A6B;          
  --bubble-them-border: 1px solid #E5F2F9; /* 边框变极浅薄冰蓝 */
  --bubble-them-shadow: 0 1px 2px rgba(162, 203, 227, 0.1);
  --bubble-them-link-color: #8AA3B3;

  /* 1. 缩小整体与高度 */
  --bubble-them-font-size: 14px;
  --bubble-them-line-height: 1.35;
  --bubble-them-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-them-radius: 12px;
  --bubble-them-radius-first: 12px 12px 12px 4px;
  --bubble-them-radius-mid: 4px 12px 12px 4px;
  --bubble-them-radius-last: 4px 12px 12px 12px;

  /* ==========================================
     相关组件同步缩小与适配
  ========================================== */
  --translation-btn-color: #8AA3B3;
  --translation-text-color: #556B7D;
  --translation-bg: rgba(225, 246, 255, 0.4);
  --translation-size: 12.5px;
  --translation-padding: 6px 10px;

  --voice-me-color: #415A6B;             /* 我方语音图标 */
  --voice-me-bar-active: #415A6B;        /* 我方波形 */
  --voice-me-bar-inactive: rgba(65, 90, 107, 0.15);
  --voice-them-color: #415A6B;           /* 对方语音图标 */
  --voice-them-bar-active: #A2CBE3;      /* 对方波形 */
  --voice-them-bar-inactive: #E5F2F9;

  --plain-avatar-radius: 12px;
  --avatar-radius: 12px;
}

/* ==========================================
   一、头像显示逻辑 (隐藏时保留占位，气泡完美对齐)
========================================== */
.msg-avatar-me-container {
  visibility: hidden !important;
}
.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  visibility: visible !important;
}

.msg-avatar-them-container {
  visibility: hidden !important;
}
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* ==========================================
   二、【我方头像】对齐与上下左右微调
========================================== */
.msg-avatar-me-container {
  align-self: flex-end !important;
  position: relative !important;
  left: -30px !important;
  top: 40px !important;
  margin-left: 10px !important; 
  overflow: visible !important;          
}

/* ==========================================
   三、【对方头像】对齐与上下左右微调
========================================== */
.msg-avatar-them-container {
  position: relative !important;
  left: 30px !important;
  top: -40px !important;
  margin-right: 10px !important;
  overflow: visible !important;          
}

/* ==========================================
   四、双方消息间距调整 (换人发言时较宽)
========================================= */
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single {
  margin-bottom: 30px !important; 
}

/* ==========================================
   五、头像：方圆形 + 白色边框 + 可旋转超大双层底框 (双层独立阴影)
========================================== */
.msg-avatar-me-inner,
.msg-avatar-them-inner,
.msg-avatar-custom {
  border-radius: 12px !important;
  border: 2px solid #FFFFFF !important;    
  box-shadow: 0 2px 6px rgba(162, 203, 227, 0.2) !important; 
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 3 !important;                   
}

.msg-avatar-me-container::before,
.msg-avatar-them-container::before {
  content: "";
  position: absolute;
  top: -1px !important;
  left: -1px !important;
  right: -1px !important;
  bottom: -1px !important;

  border-radius: 14px !important;          
  background: #FFFFFF !important;          
  border: 1px solid #EBF5FB !important;    
  box-shadow: 0 4px 10px rgba(162, 203, 227, 0.15) !important; 

  z-index: 1 !important;                   
  pointer-events: none !important;
  transform: translateY(-3px) translateX(-3px) rotate(-10deg) !important;     
}

/* ==========================================
   六、对方消息左侧：贯穿竖线与圆点 (晴空蓝)
========================================== */
.msg-avatar-them-container::after,
.msg-bubble-wrapper.msg-them::after {
  display: none !important;
  background: none !important;
}

.msg-bubble-wrapper.msg-them::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            
  transform: translateX(-50%) !important; 
  left: 20px !important; 
}

.msg-bubble-wrapper.msg-them.is-first::before {
  top: -15px !important;             
  bottom: -35px !important; 
  background: linear-gradient(#A2CBE3, #A2CBE3) no-repeat center top !important; /* 线条变晴空蓝 */
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-them.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 
  background: linear-gradient(#A2CBE3, #A2CBE3) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-them.is-last::before {
  top: -20px !important; 
  bottom: 10px !important;           
  background: 
    radial-gradient(circle, #A2CBE3 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#A2CBE3, #A2CBE3) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

.msg-bubble-wrapper.msg-them.is-single::before {
  top: -15px !important;             
  bottom: 10px !important; 
  background: 
    radial-gradient(circle, #A2CBE3 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#A2CBE3, #A2CBE3) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

/* ==========================================
   七、我方消息右侧：贯穿竖线与顶部圆点 (晴空蓝)
========================================= */
.msg-avatar-me-container::after,
.msg-bubble-wrapper.msg-me::after {
  display: none !important;
  background: none !important;
}

.msg-bubble-wrapper.msg-me::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            
  transform: translateX(50%) !important;  
  right: 20px !important; 
}

.msg-bubble-wrapper.msg-me.is-first::before {
  top: 10px !important;             
  bottom: -50px !important;          
  background: 
    radial-gradient(circle, #A2CBE3 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#A2CBE3, #A2CBE3) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; 
}

.msg-bubble-wrapper.msg-me.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 
  background: linear-gradient(#A2CBE3, #A2CBE3) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-me.is-last::before {
  top: -20px !important; 
  bottom: 30px !important;           
  background: linear-gradient(#A2CBE3, #A2CBE3) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-me.is-single::before {
  top: 5px !important;             
  bottom: -20px !important;           
  background: 
    radial-gradient(circle, #A2CBE3 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#A2CBE3, #A2CBE3) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; 
}

/* ==========================================
   八、双方头像旁侧标签 (雾霾蓝字)
========================================== */
.msg-avatar-me-inner,
.msg-avatar-them-inner {
  overflow: hidden !important;           
  border-radius: 12px !important;
}

.msg-avatar-them-container::after {
  display: block !important;
  content: "죽음" !important;
  position: absolute !important;
  white-space: nowrap !important;
  z-index: 10 !important;
  top: -3px !important;                  
  left: 45px !important;                 
  font-size: 13px !important;            
  font-weight: bold !important;          
  color: #8AA3B3 !important;             
}

.msg-bubble-wrapper.msg-them.is-first::after,
.msg-bubble-wrapper.msg-them.is-single::after {
  display: block !important;
  content: "謊話要用左耳聽" !important;
  position: absolute !important;
  white-space: nowrap !important;
  z-index: 10 !important;
  top: -25px !important;       
  left: 75px !important;       
  font-size: 11px !important;            
  font-weight: normal !important;        
  color: #8AA3B3 !important;             
}


/* ==========================================
   十、终极缩减版：隐藏聊天记录中间的独立时间戳
========================================== */
.timestamp, .chat-time, .message-date, .date-divider, .system-message, .chat-system-message, .msg-date, .im-message-date, .chat-message-date-divider,
div[class*="timestamp" i], div[class*="Divider" i], div[class*="TimeDivider" i] {
  display: none !important;
  opacity: 0 !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  pointer-events: none !important;
}

/* ==========================================
   十一至十四：顶栏重构 (高度、浅云灰背景、头像昵称居中、设置图片)
========================================== */
.chat-header-custom, 
.glass-header {
  height: 70px !important;               
  background-color: #F4F9FB !important;  /* 微带蓝调的浅云灰 */
  background-image: none !important;     
  border: none !important;               
  box-shadow: none !important;           
  backdrop-filter: none !important;      
  -webkit-backdrop-filter: none !important;
  overflow: visible !important;          
}

.chat-header-subtitle {
  display: none !important;
}

.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important; 
  display: flex !important;
  flex-direction: column-reverse !important;   
  align-items: center !important;              
  justify-content: center !important;
  background: transparent !important;
  overflow: visible !important;                
}

.chat-header-title {
  position: relative !important;
  z-index: 10 !important;                
  background: transparent !important;    
  border: none !important;
  padding: 0 !important;
  margin-bottom: 2px !important;         
  top: 16px !important;                   
  left: 0px !important;                  
  font-size: 15px !important;            
  font-weight: bold !important;          
  color: #415A6B !important;             /* 顶栏昵称变深海蓝 */
}

.header-avatar-container {
  position: relative !important;
  overflow: visible !important;          
  z-index: 5 !important;
  top: 10px !important;                  
  left: 0px !important;                  
  width: 58px !important;
  height: 58px !important;
  border: none !important;               
  box-shadow: none !important;           
  background: transparent !important;
}

.header-avatar-container img,
.header-avatar-container > div,
.chat-header-avatar {
  display: block !important;
  position: relative !important;
  z-index: 2 !important;                 
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;          
  border: none !important;               
  border-radius: 50% !important;         
  overflow: hidden !important;           
}

.header-avatar-container::after {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  z-index: 3 !important;                 
  pointer-events: none !important;       
  border: 2px solid #FFFFFF !important;  
