/* ==========================================
   二十五、终极消除重叠：头像移位空间补偿 (仅新增)
========================================== */

/* 
   💡 核心原理：
   1. 对方头像往上飞了 40px，我们就在对方消息的头部顶开 42px 的安全空间，让头像刚好落在这个空档里，绝不挡住上方的旁白！
   2. 我方头像往下掉了 40px，我们就在我方消息的底部留出 42px 的安全空间，防止掉下去的头像压住下方的消息！
*/

/* 1. 【对方消息】：给头部顶开空间，完美接住往上飞的头像和文字 */
.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-single {
  /* ▼ 这里的 42px 必须与您给对方头像设的 top: -40px 大小相匹配（这里设为 42px 完美顶开） */
  margin-top: 40px !important; 
}

/* 2. 【我方消息】：给底部留出空间，完美容纳往下掉的头像 */
.msg-bubble-wrapper.msg-me.is-last,
.msg-bubble-wrapper.msg-me.is-single {
  /* ▼ 这里的 42px 必须与您给我方头像设的 top: 40px 大小相匹配 */
  margin-bottom: 40px !important; 
}

/* 3. 【顶栏安全边距】：防止第一条消息直接钻到顶栏悬挂的那个大圆形头像后面 */
.chat-messages-area, 
.chat-message-list-custom {
  padding-top: 30px !important;
}
/* ==============================================================
   ★ iOS 灵动岛 / 刘海屏 顶部自动防挡适配 ★
============================================================== */

/* 1. 自动给顶栏增加系统反馈的安全区域高度 */
:root {
  --chat-header-height: calc(56px + env(safe-area-inset-top, 0px)) !important;
}

/* 2. 在顶栏内部用内边距将所有按钮往下推，避开灵动岛 */
.chat-header-custom {
  padding-top: env(safe-area-inset-top, 0px) !important;
  box-sizing: border-box !important;
}

/* 3. 精准数学修正：由于总高度增加了，原本的绝对居中会有点偏下。
      这个计算公式能保证你的昵称不管在灵动岛还是普通手机，都能在“可用区域”完美居中 */
.header-profile-section {
  top: calc(50% + (env(safe-area-inset-top, 0px) / 2)) !important;
}

/* ==========================================
   十一、顶栏整体样式 (高度、灰色背景、无边框与阴影)
========================================== */
