  /* 调整顶栏整体高度 */
  --chat-header-height: 70px; 
  /* 直接修改系统底层变量，强行锁死头像为正圆 */
  --chat-header-avatar-radius: 50%;
  --chat-header-avatar-size: 58px;
}

.chat-header-custom, 
.glass-header {
  height: 70px !important;               
  background-color: #F5F5F5 !important;  
  background-image: none !important;     
  border: none !important;               
  box-shadow: none !important;           
  backdrop-filter: none !important;      
  -webkit-backdrop-filter: none !important;
  overflow: visible !important;          /* 允许头像和灰色托底溢出顶栏 */
}

/* ==========================================
   十二、顶栏：头像与昵称绝对居中 (昵称在上，头像在下)
========================================== */

.chat-header-subtitle {
  display: none !important;
}

.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important; 

  display: flex !important;
  flex-direction: column-reverse !important;   
  align-items: center !important;              
  justify-content: center !important;
  background: transparent !important;
  overflow: visible !important;                
}

/* 1. 【顶栏昵称】：加上 z-index 锁死在最顶层 */
.chat-header-title {
  position: relative !important;

  /* ====================================================
     ▼ 核心修正：强行把昵称提到最顶层，彻底解决被挡住的问题
     ==================================================== */
  z-index: 10 !important;                

  background: transparent !important;    
  border: none !important;
  padding: 0 !important;

  /* ▼ 调整【昵称和头像的间距】（现在调到 2px 也绝对安全可见！） */
  margin-bottom: 2px !important;         

  /* ▼ 调整【昵称】的上下左右位置 */
  top: 16px !important;                   
  left: 0px !important;                  
  font-size: 15px !important;            
  font-weight: bold !important;          
  color: #333333 !important;
}

/* 2. 【顶栏头像外层框】：只负责定位，去掉边框和投影（改由::after在最顶层绘制） */
.header-avatar-container {
  position: relative !important;
  overflow: visible !important;          /* 确保大圆托底和相框不被切边 */
  z-index: 5 !important;

  /* ▼ 调整【头像整体】的上下左右位置 */
  top: 10px !important;                  
  left: 0px !important;                  

  width: 58px !important;
  height: 58px !important;

  border: none !important;               /* 清空原容器边框 */
  box-shadow: none !important;           /* 清空原容器投影 */
  background: transparent !important;
}

/* 3. 【顶栏头像图片本体】：强制归在【中层】，确保被最顶层的白框盖住 */
.header-avatar-container img,
.header-avatar-container > div,
.chat-header-avatar {
  display: block !important;
  position: relative !important;
  z-index: 2 !important;                 /* 中层：压在灰色托底上方，被白色相框压在下方 */
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;          
  border: none !important;               

  border-radius: 50% !important;         
  overflow: hidden !important;           /* 锁死图片为正圆 */
}

/* 4. 【终极白色头像框与投影】：强制在【顶层】绘制，100% 解决被图片遮挡的问题！ */
.header-avatar-container::after {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  z-index: 3 !important;                 /* 顶层：直接盖在头像图片正上方 */
  pointer-events: none !important;       /* 穿透点击，不影响头像点击事件 */

  /* 绘制白色头像框与阴影 */
  border: 2px solid #FFFFFF !important;  
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important; 
  border-radius: 50% !important;         
}

/* ==========================================
   十三、顶栏右侧按钮：隐身点击 + 替换设置图片
========================================== */

/* 1. 隐藏电话和视频按钮，但保证可以点击 */
.header-btn-phone, 
.header-btn-video {
