  height: 24px !important;
}

.header-btn-info svg {
  display: none !important;
}

/* ==========================================
   十四、顶栏头像后方：与背景融合的托底半圆弧线 (底层)
========================================== */
.header-avatar-container::before {
  content: "" !important;
  position: absolute !important;
  z-index: 1 !important;                 /* 底层：铺在最下面，作为顶栏向下的延伸托底 */

  /* 必须和顶栏的背景色一模一样 */
  background-color: #F5F5F5 !important;  

  /* ----------------------------------------------------
     ▼ 标注：调整弧形托底的大小和位置
     ---------------------------------------------------- */
  /* 1. 弧形的宽度：数值越大，弧线两边越平缓 */
  width: 100px !important;               

  /* 2. 弧形的高度：决定了弧线的饱满程度 */
  height: 100px !important;              

  /* 3. 保证弧线永远在头像的正中心 */
  left: 50% !important;
  transform: translateX(-50%) !important;

  /* 4. 上下位置控制：
     - 如果您觉得弧线往下包得【不够深】，把负数改小 (如 -20px, -10px)。
     - 如果觉得弧线【太长了】，把负数改大 (如 -40px, -50px)。
  */
  top: -35px !important;                 

  border-radius: 50% !important;         
}
:root {
  /* ==========================================
     我方气泡 (淡粉紫、无边框、缩小、方圆)
  ========================================== */
  --bubble-me-bg: #EEE1EA;
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #4A3D49;
  --bubble-me-border: none;
  --bubble-me-shadow: 0 1px 3px rgba(0, 0, 0, 0.02);
  --bubble-me-link-color: #8C6A85;

  /* 1. 缩小整体与高度 (调小字号、行高与上下内边距) */
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.35;
  --bubble-me-padding: 7px 12px;

  /* 2. 方圆形外观 (12px外圆角，连发时内侧4px衔接) */
  --bubble-me-radius: 12px;
  --bubble-me-radius-first: 12px 12px 4px 12px;
  --bubble-me-radius-mid: 12px 4px 4px 12px;
  --bubble-me-radius-last: 12px 4px 12px 12px;

