}

/* 屏蔽 AI 按钮原本自带的 SVG 图标 */
.input-btn-ai svg {
  display: none !important;
}
/* ==========================================
   十八、底栏与底部屏幕边缘的间距调整 (仅新增部分)
========================================== */

.input-area-custom {
  /* ----------------------------------------------------
     ▼ 标注：调整【底栏】与【屏幕最底部边缘】的距离
     - 因为现在的全面屏手机底部通常有系统自带的“安全横条”（safe-area-inset-bottom）。
     - 我们在系统安全距离的基础上，通过累加数值来控制高度：
       - 如果觉得底栏离屏幕底部太近，想【往上托起】：把 12px 改大（如 20px, 30px）。
       - 如果想让底栏更贴近底部：把 12px 改小（如 5px, 0px）。
     ---------------------------------------------------- */
  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 15px) !important;
}
/* ==========================================
   十九、隐藏输入框内部默认的占位符 (提示语)
========================================== */

/* 1. 针对各种浏览器/系统，强制将提示语变为完全透明 */
.input-box-custom::placeholder {
  color: transparent !important;
  opacity: 0 !important;
  -webkit-text-fill-color: transparent !important; /* 强制兼容 iOS 苹果设备 */
}

/* 2. 兼容部分旧版浏览器 */
.input-box-custom::-webkit-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
  -webkit-text-fill-color: transparent !important;
}
.input-box-custom::-moz-placeholder {
  color: transparent !important;
  opacity: 0 !important;
}
.input-box-custom:-ms-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
}
/* ==========================================
   二十、底栏提示栏 (以角色身份发送/旁白模式/正在回复) 变灰无边框 (新增)
========================================== */

/* 1. 强行修改系统全局变量 (使其完美适配您的灰色极简风) */
:root {
  --sendas-char-bg: #EAEAEA;             /* 提示栏背景色：修改为与灰色输入框一致 */
  --sendas-char-color: #4A3D49;          /* 文字颜色：从亮蓝色改为您的专属深紫灰 */
  --sendas-char-border: none;            /* 去掉提示栏的蓝色边框 */
  --sendas-bar-radius: 10px;             /* 圆角：修改为 10px，与扁平化输入框完美同步 */
  --sendas-bar-shadow: none;             /* 去掉投影 */
  --sendas-close-color: #8C6A85;         /* 右侧关闭按钮 X 的颜色 */
}

/* 2. 强力类名拦截器 (双重保险，100% 覆盖默认的蓝色) */
.input-sendas-bar,
.input-sendas-char-bar,
.input-sendas-narration-bar,
.input-reply-preview-bar {
  background-color: #EAEAEA !important;  /* 强行背景变灰 */
  background-image: none !important;
  border: none !important;               /* 强行无边框 */
  box-shadow: none !important;
  border-radius: 10px !important;        /* 强行与输入框相同的圆角 */
}

/* 3. 强行改变提示文字的颜色与粗细 */
.input-sendas-label,
.input-reply-preview-name {
  color: #4A3D49 !important;             /* 变更为深紫灰，告别亮蓝色 */
  font-weight: bold !important;
}

/* 4. 强行改变右侧关闭按钮 X 的颜色 */
.input-sendas-close,
.input-reply-preview-close {
  color: #8C6A85 !important;             /* 变更为浪漫的丁香紫 */
}
/* ==========================================
   二十一、调整输入框光标位置 + 发送按钮文字化 (新增)
========================================== */

/* 1. 调整输入框文字起点，让光标向右移动一点 */
.input-box-custom {
  /* 上下 6px，右侧 0，左侧 8px (用这个 8px 把光标向右推) */
  padding: 6px 0 6px 8px !important; 
}

/* 2. 发送按钮：隐藏图标，替换为紫底白字的“发送” */
.send-btn-custom {
  /* 强制绝对定位在输入框最右侧 */
  position: absolute !important;
  right: 6px !important;                 
  top: 50% !important;
  transform: translateY(-50%) !important;
  z-index: 20 !important;

  /* 给发送文字做一个精美的按钮外壳 */
  width: 46px !important;                /* 按钮宽度 (恰好装下两字) */
  height: 24px !important;               /* 按钮高度 */
  background-color: #F1E4ED !important;  /* 丁香紫底色，衬托白色文字 */
  border-radius: 6px !important;         /* 微微的圆角卡片 */

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 彻底隐藏原本发送按钮自带的纸飞机/向上箭头 SVG 图标 */
.send-btn-custom svg,
.send-btn-custom img {
  display: none !important;
}

/* 用伪元素写入“发送”两个字 */
.send-btn-custom::after {
  content: "发送" !important;
  color: #FFFFFF !important;             /* 纯白色字体 */
  font-size: 12px !important;
  font-weight: bold !important;
  letter-spacing: 2px !important;        /* 字间距稍微拉开一点，更透气 */
  margin-right: -2px !important;         /* 抵消 letter-spacing 带来的视觉偏移 */
}

/* ==========================================
   二十二、双方自己发信息不同时间的消息间距调整 (强力修正版)
========================================== */

/* 
   双重保险：
   1. 使用现代 :has() 探测器
*/

/* 【我方】跨时间连续发言：将上一条气泡的底部间距从 30px 强制压至 12px */
.msg-bubble-wrapper.msg-me:has(+ [class*="timestamp" i] + .msg-bubble-wrapper.msg-me),
.msg-bubble-wrapper.msg-me:has(+ [class*="date" i] + .msg-bubble-wrapper.msg-me),
.msg-bubble-wrapper.msg-me:has(+ .timestamp-custom + .msg-bubble-wrapper.msg-me) {
  margin-bottom: 20px !important; 
}

/* 【对方】跨时间连续发言：将上一条气泡的底部间距从 30px 强制压至 12px */
.msg-bubble-wrapper.msg-them:has(+ [class*="timestamp" i] + .msg-bubble-wrapper.msg-them),
.msg-bubble-wrapper.msg-them:has(+ [class*="date" i] + .msg-bubble-wrapper.msg-them),
.msg-bubble-wrapper.msg-them:has(+ .timestamp-custom + .msg-bubble-wrapper.msg-them) {
  margin-bottom: 20px !important; 
}

/* 
   终极兜底（负边距强力吸附）：
   如果上述方法在您的旧版系统内核中失效，这招会强制让时间戳下方的气泡“向上吸附” 18px，
   刚好把 30px 的距离抵消成 12px (30 - 18 = 12px)！
*/
[class*="timestamp" i] + .msg-bubble-wrapper.msg-me,
[class*="date" i] + .msg-bubble-wrapper.msg-me,
.timestamp-custom + .msg-bubble-wrapper.msg-me {
  margin-top: 20px !important;
}

[class*="timestamp" i] + .msg-bubble-wrapper.msg-them,
[class*="date" i] + .msg-bubble-wrapper.msg-them,
.timestamp-custom + .msg-bubble-wrapper.msg-them {
  margin-top: 20px !important;
}

/* ==========================================
   二十三、语音气泡缩小 + 全气泡隐形点击展开 + 虚线排版 (无按钮极简版)
========================================== */

:root {
  /* 1. 语音控件整体等比例精致缩小 */
  --voice-play-btn-size: 24px;
  --voice-waveform-height: 20px;
  --voice-duration-size: 10.5px;
  --voice-controls-gap: 6px;

  /* 确保按钮在系统里是存在且开启的 (切勿设为 none) */
  --voice-toggle-display: flex;

  /* 2. 转写文字区块样式调整 (去背景色、融为一体) */
  --voice-transcription-bg: transparent; 
  --voice-transcription-padding: 8px 0 0 0; 
  --voice-transcription-margin-top: 6px; 
  --voice-transcription-size: 13px;      
}

/* 3. 让语音所在的那一行作为隐形网的“画框基准” */
.voice-controls-row {
  position: relative !important;
}

/* 4. 提升【播放按钮】的图层！防止被隐形网盖住导致点不了播放 */
.voice-play-btn {
  position: relative !important;
  z-index: 20 !important;                /* 层级最高，点它就是播放 */
}

/* 5. 【核心魔法】：把展开按钮变成覆盖整个气泡的隐形大网！ */
.voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;                /* 拉伸到和气泡一样宽 */
  height: 100% !important;               /* 拉伸到和气泡一样高 */
  z-index: 10 !important;                /* 压在播放键下面，但盖住波形 */
  opacity: 0 !important;                 /* 完全隐形！ */
  margin: 0 !important;
  padding: 0 !important;
}

/* 强行杀掉开关里的文字、图标或之前添加的伪元素，确保只是一张纯净的透明网 */
.voice-transcription-toggle svg,
.voice-transcription-toggle span,
.voice-transcription-toggle::after,
.voice-transcription-toggle::before {
  display: none !important;
}

/* 6. 展开后，在语音波形和下方文字之间画一条虚线 */
.voice-transcription {
  /* 对方气泡 (白底) 用很淡的灰色虚线 */
  border-top: 1px dashed #E5E5E5 !important; 
  border-radius: 0 !important;           
}

/* 7. 我方气泡内的虚线颜色同步适配 */
.msg-me .voice-transcription {
  /* 我方气泡 (紫底) 用您文字颜色的半透明深紫灰虚线 */
  border-top: 1px dashed rgba(74, 61, 73, 0.2) !important;
}
/* ================== ★ 转账卡核心外框 (配色同步：淡粉紫半透明) ★ ================== */
.msg-transfer-card { 
    position: relative !important; 
    width: 240px !important; 
    height: 100px !important; 

    /* 采用淡粉紫 #EEE1EA 的半透明玻璃底色 */
    background-color: rgba(238, 225, 234, 0.5) !important; 
    backdrop-filter: blur(20px) saturate(160%) !important; 

    /* 边框改为晶莹的高亮淡粉白 */
    border: 1px solid rgba(255, 255, 255, 0.8) !important; 
    box-shadow: 0 6px 16px rgba(140, 106, 133, 0.08) !important; 
    border-radius: 12px !important; 
    margin-top: 4px !important; 
    overflow: hidden !important; 
    display: block !important; 
    padding: 0 !important; 

    /* 核心替换：把 SVG 的箭头颜色改成丁香紫 %238C6A85，中间隔线变粉紫虚线 */
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 40 40"><circle cx="20" cy="20" r="18" fill="none" stroke="%238C6A85" stroke-width="2.5"/><path d="M12 14h16m-4-4l4 4-4 4" fill="none" stroke="%238C6A85" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M28 26H12m4-4l-4 4 4 4" fill="none" stroke="%238C6A85" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'), linear-gradient(rgba(140, 106, 133, 0.15), rgba(140, 106, 133, 0.15)) !important; 
    background-size: 36px 36px, 100% 1px !important; 
    background-repeat: no-repeat, no-repeat !important; 
    background-position: 12px 20px, 0 74px !important; 
}

/* 清除杂项背景 */
.msg-transfer-card * { 
    background-color: transparent !important; 
    box-shadow: none !important; 
    border: none !important; 
}

/* 隐藏自带的SVG图标、头像、原版副标题 */
.msg-transfer-card svg, 
.msg-transfer-card img, 
.transfer-icon-bg, 
.msg-transfer-subtitle { 
    display: none !important; 
}

/* ================== ★ 黑色字改丁香紫：转账 (Label) ★ ================== */
.msg-transfer-label { 
    position: absolute !important; 
    top: 10px !important; 
    left: 60px !important; 
    font-size: 13px !important; 
    font-weight: 600 !important; 

    /* 统一改用浪漫的丁香紫 */
    color: #8C6A85 !important; 
    -webkit-text-fill-color: #8C6A85 !important; 
    display: block !important; 
    visibility: visible !important; 
    z-index: 10 !important; 
}

/* ================== ★ 修复金额颜色，强制变深紫灰 ★ ================== */
/* 劫持所有主题变量 */
:root, .chat-detail-screen, .msg-transfer-card {
    --transfer-amount-color: #4A3D49 !important;
    --transfer-me-amount-color: #4A3D49 !important;
    --transfer-them-amount-color: #4A3D49 !important;
