}

/* ================== ★ 转账卡核心外框 (配色同步：烟雨蓝玻璃风) ★ ================== */
.msg-transfer-card { 
    position: relative !important; 
    width: 240px !important; 
    height: 100px !important; 

    /* 采用高透明的烟雨蓝玻璃底色 */
    background-color: rgba(222, 232, 244, 0.6) !important; 
    backdrop-filter: blur(20px) saturate(160%) !important; 

    /* 晶莹的高亮淡蓝白边框 */
