    border-radius: 12px !important; 
    margin-top: 4px !important; 
    overflow: hidden !important; 
    display: block !important; 
    padding: 0 !important; 

    /* 把 SVG 箭头颜色修改为深灰色 %236B7D8F，分割线变淡蓝虚线 */
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 40 40"><circle cx="20" cy="20" r="18" fill="none" stroke="%236B7D8F" stroke-width="2.5"/><path d="M12 14h16m-4-4l4 4-4 4" fill="none" stroke="%236B7D8F" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M28 26H12m4-4l-4 4 4 4" fill="none" stroke="%236B7D8F" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'), linear-gradient(rgba(107, 125, 143, 0.15), rgba(107, 125, 143, 0.15)) !important; 
    background-size: 36px 36px, 100% 1px !important; 
    background-repeat: no-repeat, no-repeat !important; 
    background-position: 12px 20px, 0 74px !important; 
}

.msg-transfer-card * { 
    background-color: transparent !important; 
    box-shadow: none !important; 
    border: none !important; 
}

.msg-transfer-card svg, 
.msg-transfer-card img, 
.transfer-icon-bg, 
.msg-transfer-subtitle { 
    display: none !important; 
}

/* ================== ★ 深雨蓝字：转账 (Label) ★ ================== */
.msg-transfer-label { 
    position: absolute !important; 
    top: 10px !important; 
    left: 60px !important; 
    font-size: 13px !important; 
    font-weight: 600 !important; 
    color: #6B7D8F !important;             
    -webkit-text-fill-color: #6B7D8F !important; 
    display: block !important; 
    visibility: visible !important; 
    z-index: 10 !important; 
