/* ================== ★ 修复金额颜色，强制变深海蓝灰 ★ ================== */
:root, .chat-detail-screen, .msg-transfer-card {
    --transfer-amount-color: #354454 !important;
    --transfer-me-amount-color: #354454 !important;
    --transfer-them-amount-color: #354454 !important;
    --transfer-success-amount-color: #354454 !important;
    --transfer-rejected-amount-color: #354454 !important;
    --transfer-expired-amount-color: #354454 !important;
}

.msg-transfer-amount {
