}
.msg-transfer-status-text > *:not(:first-child) {
    display: none !important;
}
.msg-transfer-card [class*="expire"],
.msg-transfer-card [class*="time"],
.msg-transfer-card [class*="date"] {
    display: none !important;
}
.msg-transfer-card::before,
.msg-transfer-card::after { 
