/* ================== ★ 彻底抹除时间戳物理间隙 ★ ================== */
.timestamp-custom, .date-divider-custom, .msg-timestamp-wrapper, .chat-timestamp, 
[class*="timestamp"], [class*="datetime"], .message-list-item[data-type*="time"] {
