}

.msg-reply-detached-me::after {
  right: 10px !important;            
  left: auto !important;
}
/* ==========================================
   二十五、终极消除重叠：头像移位空间补偿 (仅新增)
========================================== */

/* 
   💡 核心原理：
   1. 对方头像往上飞了 40px，我们就在对方消息的头部顶开 42px 的安全空间，让头像刚好落在这个空档里，绝不挡住上方的旁白！
   2. 我方头像往下掉了 40px，我们就在我方消息的底部留出 42px 的安全空间，防止掉下去的头像压住下方的消息！
*/

/* 1. 【对方消息】：给头部顶开空间，完美接住往上飞的头像和文字 */
.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-single {
  /* ▼ 这里的 42px 必须与您给对方头像设的 top: -40px 大小相匹配（这里设为 42px 完美顶开） */
  margin-top: 40px !important; 
}

/* 2. 【我方消息】：给底部留出空间，完美容纳往下掉的头像 */
.msg-bubble-wrapper.msg-me.is-last,
.msg-bubble-wrapper.msg-me.is-single {
  /* ▼ 这里的 42px 必须与您给我方头像设的 top: 40px 大小相匹配 */
  margin-bottom: 40px !important; 
}

/* 3. 【顶栏安全边距】：防止第一条消息直接钻到顶栏悬挂的那个大圆形头像后面 */
.chat-messages-area, 
.chat-message-list-custom {
  padding-top: 30px !important;
}
/* ==============================================================
   ★ iOS 灵动岛 / 刘海屏 顶部自动防挡适配 ★
============================================================== */

/* 1. 自动给顶栏增加系统反馈的安全区域高度 */
:root {
  --chat-header-height: calc(56px + env(safe-area-inset-top, 0px)) !important;
}

/* 2. 在顶栏内部用内边距将所有按钮往下推，避开灵动岛 */
.chat-header-custom {
  padding-top: env(safe-area-inset-top, 0px) !important;
  box-sizing: border-box !important;
}

/* 3. 精准数学修正：由于总高度增加了，原本的绝对居中会有点偏下。
      这个计算公式能保证你的昵称不管在灵动岛还是普通手机，都能在“可用区域”完美居中 */
.header-profile-section {
  top: calc(50% + (env(safe-area-inset-top, 0px) / 2)) !important;
}

/* ===================================================
    聊天页
   =================================================== */

/* 1. 核心变量：仅在包含“设置/电话/视频”按钮的【聊天顶栏】上生效，绝不污染设置页 */
.chat-detail-screen .glass-header:has(.header-btn-info, .header-btn-phone, .header-btn-video),
.chat-detail-screen .chat-header-custom:has(.header-btn-info, .header-btn-phone, .header-btn-video) {
    --chat-header-height: 110px !important;
    --chat-header-bg: transparent !important;
    --chat-header-border: transparent !important;
    --chat-header-blur: 0px !important;

    /* ---------------------------------------------------
       【位置调整 A】：控制【左侧返回组（图标 + 13.14km）】的上下和左右位置
       --------------------------------------------------- */
    --btn-back-translate-y: 21px !important; 
    --btn-back-translate-x: 8px !important;  

    /* ---------------------------------------------------
       【位置调整 B】：控制【右侧三个组件】在虚线下方的水平/垂直偏移
       --------------------------------------------------- */
    --btn-phone-translate-y: 21px !important; 
    --btn-phone-translate-x: 10px !important;  

    --btn-video-translate-y: 21px !important; 
    --btn-video-translate-x: 0px !important;  

    --btn-info-translate-y: 21px !important;  
    --btn-info-translate-x: -8px !important;  

    /* ---------------------------------------------------
       【间距调整 C】：控制右侧三个组件（电话、文本1、文本2）之间的水平间距
       --------------------------------------------------- */
    --header-btn-gap: 8px !important;        
}

/* 2. 彻底隐藏右侧默认的 SVG 图标（电话、视频、设置）以及左侧默认返回箭头 */
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .header-btn-back svg,
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .header-btn-phone svg,
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .header-btn-video svg,
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .header-btn-info svg {
