  --plus-btn-icon: url('https://pic1.imgdb.cn/item/6a24382c0c24090b102862ff.png');
  --send-btn-icon: url('https://pic1.imgdb.cn/item/6a24382c0c24090b102862ff.png');
  --stop-btn-icon: url('https://pic1.imgdb.cn/item/6a24382c0c24090b102862ff.png');
