  --input-box-placeholder: #b8e4f5;
  --input-box-radius: 22px;
  --input-box-padding: 10px 18px;
  --input-box-border: 1px solid rgba(180,225,248,0.7);
  --input-box-shadow: 0 2px 8px rgba(58,174,216,0.1);
  --input-caret-color: #3aaed8;

  /* 发送按钮 */
  --send-btn-bg: #3aaed8;
  --send-btn-size: 34px;
  --send-btn-radius: 50%;
  --send-btn-shadow: 0 2px 10px rgba(58,174,216,0.4);
