position: absolute !important;
top: -55px !important; 
right: 60px !important; 
background: rgba(255, 255, 255, 0.6) !important; 
backdrop-filter: blur(10px) !important;
-webkit-backdrop-filter: blur(10px) !important;
border: 1px solid #dee2e6 !important; 
border-radius: 20px 0 0 20px !important;
width: 50px !important;
height: 24px !important;
box-shadow: -2px 2px 6px rgba(0,0,0,0.02) !important;
transform: translateX(10px) !important;
}
.input-btn-mic::after {
content: "Voice";
font-size: 10px;
color: #868e96;
position: absolute;
top: 50%; left: 50%;
transform: translate(-50%, -50%);
}
/* 3. 表情键（右半边） */
.input-btn-sticker {
position: absolute !important;
top: -55px !important;
right: 10px !important;
background: rgba(255, 255, 255, 0.6) !important;
backdrop-filter: blur(10px) !important;
-webkit-backdrop-filter: blur(10px) !important;
border: 1px solid #dee2e6 !important;
border-left: none !important; 
border-radius: 0 20px 20px 0 !important;
width: 50px !important;
height: 24px !important;
box-shadow: 2px 2px 6px rgba(0,0,0,0.02) !important;
transform: translateX(10px) !important;
}
.input-btn-sticker::after {
content: "Memes";
font-size: 10px;
color: #868e96;
position: absolute;
top: 50%; left: 50%;
transform: translate(-50%, -50%);
}

/* 解决打字时字和星星重叠 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-box-custom {
padding-right: 52px !important;
}
/* 1. 左边星星往上提一点，让它视觉居中 */
.input-btn-plus {
transform: translate(2px, -3px) !important; 
}
/* 2. 胶囊整体往左挪，修正偏右的问题 */
.input-action-bar-custom {
transform: translateX(-4px) !important; 
}
/* === 控制台专属配色（作者原味版） === */
.nuo-console-toggle-bar, .nuo-console-toggle-btn {
--console-toggle-bg: #f8f9fa;
--console-toggle-color: #212529;
}
.nuo-console-panel {
--console-panel-bg: rgba(248, 249, 250, 0.96);
--console-panel-color: #212529;
}
/* 层级稍微压低一点，免得打架 */
.nuo-console-shell {
--console-shell-z: 10;
}

/* === 2. 我方最后一条消息智能避让胶囊 === */
/* 只有在输入框为空（胶囊存在）时，才往上顶。打字时胶囊消失，气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important; 
}
/* === 2. 胶囊智能躲避：让 CSS 自己做加法（修复重叠bug） === */
.chat-detail-screen {
--offset-reply: 0px;
--offset-sendas-char: 0px;
--offset-sendas-narr: 0px;
--offset-console: 0px;
}
/* 各自独立报身高，绝不混淆 */
.chat-detail-screen:has(.input-reply-preview-bar) { --offset-reply: 50px; }
.chat-detail-screen:has(.input-sendas-char-bar) { --offset-sendas-char: 40px; }
.chat-detail-screen:has(.input-sendas-narration-bar) { --offset-sendas-narr: 40px; }
.chat-detail-screen:has(.nuo-console-shell) { --offset-console: 45px; }
/* 胶囊自动往上飞，高度 = 所有出现的条的高度总和 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
/* 胶囊自动往上飞，并强行统一两半边的动画 */
.input-btn-mic, .input-btn-sticker {
margin-top: calc(-1 * (var(--offset-reply) + var(--offset-sendas-char) + var(--offset-sendas-narr) + var(--offset-console))) !important;
transition: all 0.2s cubic-bezier(0.25, 0.8, 0.25, 1) !important;}
}
/* 控制台出现时，保证胶囊在最上层不被盖住 */
.chat-detail-screen:has(.nuo-console-shell) .input-btn-mic,
.chat-detail-screen:has(.nuo-console-shell) .input-btn-sticker {
z-index: 50 !important;
}

/* === 3. 我方气泡避让胶囊 === */
/* 没打字（胶囊在）时，气泡往上躲 30px；一打字（胶囊消失），气泡自动掉下来 */
.chat-detail-screen:has(.input-box-custom:placeholder-shown) [data-absolute-last="true"][data-sender="me"] {
margin-bottom: 30px !important;
transition: margin-bottom 0.2s ease !important; 
}
/* === 气泡底部便签虚线（首尾封边 + 左右分色版） === */
/* 1. 给第一条、最后一条、单条气泡腾出底部空间 */
.msg-bubble-wrapper.is-first .bubble-them-custom,
.msg-bubble-wrapper.is-last .bubble-them-custom,
.msg-bubble-wrapper.is-single .bubble-them-custom,
.msg-bubble-wrapper.is-first .bubble-me-custom,
.msg-bubble-wrapper.is-last .bubble-me-custom,
.msg-bubble-wrapper.is-single .bubble-me-custom {
position: relative !important;
padding-bottom: 10px !important;
}

/* 2. 对方气泡（左边）的虚线：稍微加深一点的灰（用半透明黑） */
.msg-bubble-wrapper.is-first .bubble-them-custom::after,
.msg-bubble-wrapper.is-last .bubble-them-custom::after,
.msg-bubble-wrapper.is-single .bubble-them-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(0, 0, 0, 0.12) !important; 
pointer-events: none;
}
/* 3. 我方气泡（右边）的虚线：专属紫色加透明度 -> 换成灰 */
.msg-bubble-wrapper.is-first .bubble-me-custom::after,
.msg-bubble-wrapper.is-last .bubble-me-custom::after,
.msg-bubble-wrapper.is-single .bubble-me-custom::after {
content: "";
position: absolute;
left: 12px;
right: 12px;
bottom: 7px;
border-bottom: 1px dashed rgba(134, 142, 150, 0.6) !important; 
pointer-events: none;
}
/* === 独立翻译条（往内缩 + 紫色统一版） === */
:root {
--translation-always-show: 1;
}
.msg-translation-wrapper { display: none !important; }

.msg-translation-detached {
display: block !important;
margin-top: 4px !important;
}

/* 对方的翻译整体往右挪一点 */
.msg-translation-detached-them {
margin-left: 4px !important; 
}

/* 文字变成浅紫色 -> 浅灰 */
.msg-translation-detached-content {
background: transparent !important;
color: #868e96 !important; 
padding: 4px 0 4px 12px !important;
font-size: 13px !important;
position: relative !important;
box-shadow: none !important;
}

/* 竖条也变成一样的浅紫色 -> 浅灰 */
.msg-translation-detached-content::before {
content: "" !important;
position: absolute !important;
left: 0 !important;
top: 6px !important;
bottom: 6px !important;
width: 4px !important;
border-radius: 4px !important;
background-color: #868e96 !important; 
}

/* 把装了图片/表情包的气泡背景和边框变透明（排除引用框里的图片） */
.bubble-me-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img)),
.bubble-them-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img)) {
background: transparent !important;
border: none !important;
box-shadow: none !important;
padding: 0 !important;
}
/* 去掉图片/表情包底部的虚线（同样排除） */
.bubble-me-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img))::after,
.bubble-them-custom:has(img:not(.msg-reply-block-detached img):not(.msg-reply-block img))::after {
display: none !important;
}
/* 控制图片大小 + 修复位置 */
.msg-bubble-container img {
max-width: 110px !important; 
max-height: 170px !important;
width: auto !important;
height: auto !important;
object-fit: contain !important;
border-radius: 8px !important;
}
/* 我发的图片靠右贴头像 */
.msg-me .msg-bubble-container img {
display: block !important;
margin-left: auto !important;
}
/* 对方发的图片靠左贴头像 */
.msg-them .msg-bubble-container img {
display: block !important;
margin-right: auto !important;
}
/* 强制缩小引用框里的图片并裁成正方形 */
.msg-bubble-wrapper .msg-reply-block-detached img,
.msg-reply-detached-text img {
    width: 28px !important;
    height: 28px !important;
    max-width: 28px !important; 
    max-height: 28px !important;
    object-fit: cover !important; 
    aspect-ratio: 1 / 1 !important; 
    border-radius: 3px !important;
    vertical-align: middle !important;
    display: inline-block !important;
    margin: 0 4px !important;
}
/* 引用框内容顶部齐平 */
.msg-reply-block-detached {
    align-items: flex-start !important; 
}
/* 名字稍微往下压一点，和图片视觉边缘对齐 */
.msg-reply-detached-name {
    margin-top: 0px !important; 
}

/* ============================================
    天使 蕾丝 小猫尖 by atne
    禁二传二改 自定义和适配调整在开头🤍标注
    仅适配素净
   ============================================ */
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@100..900&display=swap');

/* ----------🤍custom🤍---------- */
:root {
  /* id */
  --custom-id-text: "@id";

  /* 个签 */
  --custom-title-caption: " 我知这世界本如露水般短暂，然而，然而。 ";

  /* 占位符 */
  --custom-placeholder-text: "Send something…";

  /* 图片 reaction tag*/
  --img-tag-1: "🤍 520";
  --img-tag-2: "🪽 134";

/* user 引用条长度 */
  --reply-text-me-max: 200px; /* 引用条太长缩小 反之增大 */
}

/* ----------🤍end🤍---------- */

/* ----------variables---------- */
:root {
  --plain-avatar-size: 35px;
  --plain-avatar-radius: 50%;
  --plain-avatar-gap: 8px;
  --plain-content-max-width: 78%;
  --plain-gap-between-groups: 36px;
  --plain-gap-within-group: 16px;
  --plain-padding-right-them: 40px;
  --plain-padding-left-me: 40px;
  --detached-max-width: min(54vw, 260px);
  --reply-name-max: 160px;
  --reply-text-them-max: 220px;   
  --quote-side-offset: 7vw;
  --quote-rail-width: 80vw;
  --thinking-btn-bg: transparent;
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-color: #9a9aa5;
  --reply-bar-accent: rgb(227, 220, 224);
  --chat-header-avatar-size: 48px;
  --plus-btn-icon: url('https://atnefallhmhz.vercel.app/f/menuicon-0889qs.png');

}
/* ----------1. bubbles---------- */
.msg-plain {
  position: relative;
  z-index: 0;
  overflow: visible;
  border-radius: 0 !important;
  padding: 7px 12px 7px !important;
  color: #3f3f3f !important;
}
.msg-plain-me {
  background: rgba(240, 234, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
  color: #3f3f3f !important;
}
.msg-plain-them {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  color: #3f3f3f !important;
}
.msg-plain-me.plain-last,
.msg-plain-me.plain-single,
.msg-plain-them.plain-first,
.msg-plain-them.plain-single {
  border-bottom: 0 !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-them.is-first {
  margin-bottom: calc(var(--plain-gap-within-group) + 2px) !important;
}
.msg-bubble-wrapper,
.msg-content-stack {
  overflow: visible;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before,
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  top: calc(100% - 1px);
  height: 12px;
  background-repeat: repeat-x;
  background-size: auto 71px;
  background-position: left -24px;
  pointer-events: none;
  z-index: 1;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/bluelace-dyhi6c.png");
}
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/pinklace-t2hrld.png");
}
.msg-plain-me.plain-last::after,
.msg-plain-me.plain-single::after {
  content: "";
  position: absolute;
  right: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/bluewing-ra1cz8.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: right center;
  animation: wing-sway 2s ease-in-out infinite;
}
.msg-plain-them.plain-first::after,
.msg-plain-them.plain-single::after {
  content: "";
  position: absolute;
  left: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/pinkwing-t1kiwd.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: left center;
  animation: wing-sway 2s ease-in-out infinite;
}
@keyframes wing-sway {
  0%, 100% { transform: translateY(-50%) rotate(6deg); }
  50%      { transform: translateY(-50%) rotate(-6deg); }
}
/* ----------2. avatars---------- */

[data-theme-style="plain"] .msg-avatar-them-container {
  visibility: hidden;
  pointer-events: none;
  position: relative;
}
[data-theme-style="plain"] .msg-avatar-me-container {
  visibility: hidden;
  pointer-events: none;
  position: relative;
  height: 0 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

[data-theme-style="plain"] .msg-avatar-them-container.is-first,
[data-theme-style="plain"] .msg-avatar-them-container.is-single {
  visibility: visible;
  pointer-events: auto;
  align-self: flex-start !important;   /* ← 关键：锁定顶边为起点 */
  transform: translateY(-10px);         /* 想更错位就调这个数 */
}
[data-theme-style="plain"] .msg-avatar-me-container.is-last,
[data-theme-style="plain"] .msg-avatar-me-container.is-single {
  visibility: visible;
  pointer-events: auto;
  height: auto !important;
  align-self: flex-end !important;
  transform: translateY(20px);
}
[data-theme-style="plain"] .msg-avatar-them-container::before,
[data-theme-style="plain"] .msg-avatar-me-container::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: calc(100% + 2px);
  transform: translateX(calc(-50% - 1px));
  width: 22px;
  height: 12px;
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  pointer-events: none;
}
[data-theme-style="plain"] .msg-avatar-them-container::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/pinkring-mz8cuk.png");
}
[data-theme-style="plain"] .msg-avatar-me-container::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/bluering-pfjnqb.png");
}
.msg-avatar-them-ghost {
  pointer-events: none !important;
}
/* ----------3. read status---------- */
[data-theme-style="plain"] .msg-me.is-last .msg-status-custom,
[data-theme-style="plain"] .msg-me.is-single .msg-status-custom {
  margin-top: 12px !important;
}
.timestamp-custom {
  margin-bottom: 30px !important;
}
/* ----------4. thinking button---------- */
.nuo-thinking-wrap {
  width: max-content !important;
  max-width: none !important;
  transform: translateX(-2px) !important;
}
.nuo-thinking-btn {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
}
.nuo-thinking-arrow,
.nuo-thinking-icon {
  display: none !important;
}
.nuo-thinking-label {
  white-space: nowrap !important;
}
.nuo-thinking-label::before {
  content: "‎┈─┈˖˚⊹ ⋆ ";
}
.nuo-thinking-label::after {
  content: " ⋆ ⊹˚˖ ┈─┈";
}
/* ----------5. translation---------- */
.msg-translation-wrapper {
  display: contents !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
}
.msg-translation-content {
  display: none !important;
}
.msg-translation-btn {
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
  width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1.2 !important;
  opacity: 0.85 !important;
  pointer-events: auto !important;
}
.msg-translation-btn::before {
  content: "ʚ✞ɞ" !important;
  display: inline-flex !important;
  margin-right: 2px !important;
  color: currentColor !important;
  font-size: 11px !important;
  line-height: 1 !important;
}
.msg-translation-btn :is(svg, i, img, [data-icon], [aria-hidden="true"], [role="img"], .icon, .lucide, [class*="icon"]) {
  display: none !important;
}
.msg-plain-me .msg-translation-btn {
  position: absolute !important;
  top: calc(100% + 12px) !important;
  right: 8px !important;
  left: auto !important;
  z-index: 50 !important;
}
.msg-plain-them .msg-translation-btn {
  position: absolute !important;
  top: calc(100% + 12px) !important;
  left: -8px !important;
  right: auto !important;
  z-index: 50 !important;
}
.msg-plain-me.plain-first .msg-translation-btn,
.msg-plain-them.plain-first .msg-translation-btn {
  top: calc(100% + 20px) !important;
}
/* keep this order: collapsed 14 -> first collapsed 22 -> expanded 20 */
.msg-plain-me:has(.msg-translation-btn),
.msg-plain-them:has(.msg-translation-btn) {
  position: relative !important;
  overflow: visible !important;
  margin-bottom: 14px !important;
}
.msg-plain-me.plain-first:has(.msg-translation-btn),
.msg-plain-them.plain-first:has(.msg-translation-btn) {
  margin-bottom: 22px !important;
}
.msg-plain-me:has(.msg-translation-detached-content),
.msg-plain-them:has(.msg-translation-detached-content) {
  margin-bottom: 20px !important;
}
.msg-translation-detached {
  display: block !important;
  width: fit-content !important;
  max-width: var(--detached-max-width) !important;
  margin: 11px 0 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.is-first .msg-translation-detached {
  margin-top: 18px !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-them.is-first:has(.msg-translation-detached-content) {
  margin-bottom: calc(var(--plain-gap-within-group) + 1px) !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-me.is-first:has(.msg-translation-detached-content) {
  margin-bottom: calc(var(--plain-gap-within-group) - 1px) !important;
}
.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-me { align-self: flex-end !important; }
.msg-translation-detached-content {
  display: inline-block !important;
  width: fit-content !important;
  max-width: var(--detached-max-width) !important;
  margin: 0 !important;
  border-radius: 0 !important;
  padding: 5px 10px !important;
  color: #3f3f3f !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  white-space: normal !important;
  overflow-wrap: anywhere !important;
  text-align: left !important;
}
.msg-me .msg-translation-detached-content {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
}
.msg-them .msg-translation-detached-content {
  background: rgba(240, 233, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
}
/* ----------6. voice---------- */
.voice-msg,
.voice-msg-me,
.voice-msg-them {
  display: flex !important;
  flex-direction: column !important;
  gap: 5px !important;
  background: none !important;
  border: none !important;
  position: static !important;
}
.voice-msg-me { align-items: flex-end !important; }
.voice-msg-them { align-items: flex-start !important; }
.msg-plain-me:has(.voice-msg),
.msg-plain-them:has(.voice-msg) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.msg-plain-me:has(.voice-msg)::before,
.msg-plain-them:has(.voice-msg)::before,
.msg-plain-me:has(.voice-msg)::after,
.msg-plain-them:has(.voice-msg)::after {
  content: none !important;
  display: none !important;
}
.voice-controls-row {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  width: fit-content !important;
  max-width: 100% !important;
  border-radius: 0 !important;
  padding: 7px 12px !important;
}
.msg-me .voice-controls-row {
  background: rgba(240, 233, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
}
.msg-them .voice-controls-row {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
}
.voice-play-btn,
.voice-download-btn {
  background: transparent !important;
  border: none !important;
