/* ========== 补丁：subtext chip ========== */

/* 1. toggle 图标换成和翻译一样的颜文字 ʚ✞ɞ */
.msg-subtext-toggle {
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
  display: inline-flex !important;
  align-items: center !important;
  transform: none !important;
}
.msg-subtext-toggle svg { display: none !important; }
.msg-subtext-toggle::before {
  content: "ʚ✞ɞ" !important;
  color: #9a9aa5 !important;
  -webkit-text-fill-color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1 !important;
}

/* 2. 外层 chip：清背景/边框/阴影，不倾斜，放开宽度；上方留空 */
.msg-subtext-chip,
.msg-subtext-chip.is-me,
.msg-subtext-chip.is-open {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 16px !important;
  max-width: 250px !important;
  position: relative !important;     /* 给展开态的透明点击层做定位基准 */
}

/* 展开后：隐藏 toggle 图标 + 不占位；toggle 变成覆盖气泡的透明点击层 → 点气泡收起 */
.msg-subtext-toggle.is-open {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 5 !important;             /* 盖在气泡上方接收点击 */
  background: none !important;
  cursor: pointer !important;
}
.msg-subtext-toggle.is-open::before {
  content: "" !important;            /* 展开后不显示颜文字 */
}

/* 3. subtext 文字：去背景，边框保留，不倾斜，中灰字，放宽，蓝波点盖在文字上方 */
.msg-subtext-body {
  position: relative !important;
  box-sizing: border-box !important;
  background: none !important;
  border: 1px solid #ebe7eb !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 0px !important;
  padding: 3px 12px !important;
  min-width: 0px !important;
  max-width: none !important;
  font-size: 12px !important;
  color: #808080 !important;
  -webkit-text-fill-color: #808080 !important;
}
.msg-subtext-body::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 2 !important;
  background:
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 8px 8px / 16px 16px repeat !important;
}

.typing {
  display: inline-flex;
  align-items: center;
  background-color: rgba(234, 235, 241, 0.7);
  border: 1px solid #ebe7eb !important;
  border-radius: 18px;
  padding: 8px 14px;
