/* nuojiji-bubble-config: {"themeStyle":"qq","bubbleStyle":"#06C755","partnerBubbleStyle":"#ffffff","bubbleTextColor":"#ffffff","partnerBubbleTextColor":"#000000","avatarSize":40,"avatarShape":"circle"} */

:root {
  /* AI对方气泡配置 */
  --bubble-them-bg: #EAF4FD;
  --bubble-them-border: 1px solid #D8EDFF;
  --bubble-them-padding: 3px 11px;
  --bubble-them-radius: 10px;
  --bubble-them-shadow: none;

  /* 用户我方气泡配置 */
  --bubble-me-bg: #D8EDFF;
  --bubble-me-color: #383838;
  --bubble-me-padding: 4px 11px;
  --bubble-me-radius: 10px;
  --bubble-me-shadow: none;

  /* 消息间距 */
  --chat-messages-gap: 0px;
  --plain-gap-between-groups: 24px;
  --plain-gap-within-group: 0px;

  /* 头像变量 */
  --avatar-size: 35px;
  --plain-avatar-size: 35px;
  --avatar-radius: 8px;
  --plain-avatar-radius: 8px;
}

/* 消息容器基础 */
.msg-bubble-wrapper {
  position: relative !important;
  padding-top: 0px !important;
}

/* 仅【第一条/单条】预留头像顶部空白 + 强制增加与上方消息的间距 */
.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-single {
  padding-top: 20px !important;
  margin-top: 16px !important;
}

/* 气泡强制位移 */
.msg-bubble-wrapper:has(.msg-avatar-them-container) {
  padding-left: 12px !important;
}
.msg-bubble-wrapper:has(.msg-avatar-them-container) > *:not([class*="avatar"]) {
  margin-left: 8px !important;
}

.msg-bubble-wrapper:has(.msg-avatar-me-container) {
  padding-right: 12px !important;
}
.msg-bubble-wrapper:has(.msg-avatar-me-container) > *:not([class*="avatar"]) {
  margin-right: 8px !important;
}

/* 头像位置调整 */
.msg-avatar-them-container,
.msg-avatar-me-container {
  position: absolute !important;
  top: -20px !important;
  width: 35px !important;
  height: 35px !important;
}

/* AI头像往左移 */
.msg-avatar-them-container {
  left: -3px !important;
}

/* 用户头像往右移 */
.msg-avatar-me-container {
  right: -3px !important;
}

.msg-avatar-me-inner,
.msg-avatar-them-inner {
  width: 100% !important;
  height: 100% !important;
  border-radius: 8px !important;
}

/* 同组只显示第一条/单条头像 */
.msg-avatar-them-container.is-mid,
.msg-avatar-them-container.is-last,
.msg-avatar-me-container.is-mid,
.msg-avatar-me-container.is-last {
  display: none !important;
}

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single,
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single {
  display: block !important;
}

/* ========== 竖线 ========== */
.msg-bubble-wrapper:has(.msg-avatar-them-container)::before,
.msg-bubble-wrapper:has(.msg-avatar-me-container)::before {
  content: "";
  position: absolute;
  width: 3px;
  background-color: #E8F5FF;   
  border-radius: 2px;         
  z-index: 0;
  pointer-events: none;
}

.msg-bubble-wrapper:has(.msg-avatar-them-container)::before {
  left: 3px;
}

.msg-bubble-wrapper:has(.msg-avatar-me-container)::before {
  right: 3px;
}

.msg-bubble-wrapper.is-first:has(.msg-avatar-them-container)::before,
.msg-bubble-wrapper.is-first:has(.msg-avatar-me-container)::before {
  top: 24px;
  bottom: -12px;
}

.msg-bubble-wrapper.is-single:has(.msg-avatar-them-container)::before,
.msg-bubble-wrapper.is-single:has(.msg-avatar-me-container)::before {
  top: 24px;
  bottom: 4px;
}

.msg-bubble-wrapper.is-mid:has(.msg-avatar-them-container)::before,
.msg-bubble-wrapper.is-mid:has(.msg-avatar-me-container)::before {
  top: -12px;
  bottom: -12px;
