/* ==============================================================
   ★ 分离式独立气泡（双气泡）+ 隐藏昵称 + 冰蓝白透方圆微缩版 + 连线 ★
============================================================== */

.msg-reply-block { 
  display: none !important; 
}

.msg-reply-block-detached { 
  display: flex !important; 
  order: -1 !important;        
  position: relative !important;
  flex-direction: column !important;

  /* 统一改用优雅的冰蓝白透光玻璃底色 */
  background: rgba(240, 249, 255, 0.8) !important;
  /* 极细的蓝灰色半透明柔和边框 */
  border: 1px solid rgba(139, 168, 184, 0.2) !important;

  border-radius: 6px !important;    
  padding: 4px 10px !important;
  margin-bottom: 24px !important; 
  margin-top: 0px !important;
  justify-content: center !important;
}

:root {
  --reply-detached-border-left: none !important;
  --reply-detached-me-border-left: none !important;
  --reply-detached-them-border-left: none !important;
  --reply-detached-flex-direction: column !important;
  --reply-detached-text-whitespace: normal !important; 
}

.msg-reply-detached-name {
  display: none !important;
}

.msg-reply-detached-text {
  /* 字体颜色改用深海蓝灰 #415A6B */
  color: #415A6B !important;
  -webkit-text-fill-color: #415A6B !important;
  font-size: 13px !important;
  line-height: 1.3 !important;  
