/* 1. toggle 图标换成和翻译一样的颜文字 ʚ✞ɞ */
.msg-subtext-toggle {
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
  display: inline-flex !important;
  align-items: center !important;
  transform: none !important;
}
.msg-subtext-toggle svg { display: none !important; }
.msg-subtext-toggle::before {
  content: "ʚ✞ɞ" !important;
  color: #9a9aa5 !important;
  -webkit-text-fill-color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1 !important;
}

/* 2. 外层 chip：清背景/边框/阴影，不倾斜，放开宽度；上方留空 */
.msg-subtext-chip,
.msg-subtext-chip.is-me,
.msg-subtext-chip.is-open {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 16px !important;
  max-width: 250px !important;
  position: relative !important;     /* 给展开态的透明点击层做定位基准 */
}

/* 展开后：隐藏 toggle 图标 + 不占位；toggle 变成覆盖气泡的透明点击层 → 点气泡收起 */
.msg-subtext-toggle.is-open {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 5 !important;             /* 盖在气泡上方接收点击 */
  background: none !important;
  cursor: pointer !important;
}
.msg-subtext-toggle.is-open::before {
  content: "" !important;            /* 展开后不显示颜文字 */
}

/* 3. subtext 文字：去背景，边框保留，不倾斜，中灰字，放宽，蓝波点盖在文字上方 */
.msg-subtext-body {
  position: relative !important;
  box-sizing: border-box !important;
  background: none !important;
  border: 1px solid #ebe7eb !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 0px !important;
  padding: 3px 12px !important;
  min-width: 0px !important;
  max-width: none !important;
  font-size: 12px !important;
  color: #808080 !important;
  -webkit-text-fill-color: #808080 !important;
}
.msg-subtext-body::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 2 !important;
  background:
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 8px 8px / 16px 16px repeat !important;
}

.typing {
  display: inline-flex;
  align-items: center;
  background-color: rgba(234, 235, 241, 0.7);
  border: 1px solid #ebe7eb !important;
  border-radius: 18px;
  padding: 8px 14px;
}

/* dot 换成图片 */
.typing .dot,
.typing::after {
  content: "";
  display: inline-block;
  width: 10px;               /* 按需调整 */
  height: 10px;              /* 按需调整 */
  background-image: url("https://atnefallhmhz.vercel.app/f/subtext-zh7bvc.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
}

.nuo-typing-bubble {
  background-color: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  border-radius: 0 !important;
}

/* ============================================
    天使 蕾丝 小猫尖 by atne
    禁二传二改 自定义和适配调整在开头🤍标注
    仅适配素净
   ============================================ */
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@100..900&display=swap');

/* ----------🤍custom🤍---------- */
:root {
  /* id */
  --custom-id-text: "@id";

  /* 个签 */
  --custom-title-caption: " 我知这世界本如露水般短暂，然而，然而。 ";

  /* 占位符 */
  --custom-placeholder-text: "Send something…";

  /* 图片 reaction tag*/
  --img-tag-1: "🤍 520";
  --img-tag-2: "🪽 134";

/* user 引用条长度 */
  --reply-text-me-max: 200px; /* 引用条太长缩小 反之增大 */
}

/* ----------🤍end🤍---------- */

/* ----------variables---------- */
:root {
  --plain-avatar-size: 35px;
  --plain-avatar-radius: 50%;
  --plain-avatar-gap: 8px;
  --plain-content-max-width: 78%;
  --plain-gap-between-groups: 36px;
  --plain-gap-within-group: 16px;
  --plain-padding-right-them: 40px;
  --plain-padding-left-me: 40px;
  --detached-max-width: min(54vw, 260px);
  --reply-name-max: 160px;
  --reply-text-them-max: 220px;   
  --quote-side-offset: 7vw;
  --quote-rail-width: 80vw;
  --thinking-btn-bg: transparent;
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-color: #9a9aa5;
  --reply-bar-accent: rgb(227, 220, 224);
  --chat-header-avatar-size: 48px;
  --plus-btn-icon: url('https://atnefallhmhz.vercel.app/f/menuicon-0889qs.png');

}
/* ----------1. bubbles---------- */
.msg-plain {
  position: relative;
  z-index: 0;
  overflow: visible;
  border-radius: 0 !important;
  padding: 7px 12px 7px !important;
  color: #3f3f3f !important;
}
.msg-plain-me {
  background: rgba(240, 234, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
  color: #3f3f3f !important;
}
.msg-plain-them {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  color: #3f3f3f !important;
}
.msg-plain-me.plain-last,
.msg-plain-me.plain-single,
.msg-plain-them.plain-first,
.msg-plain-them.plain-single {
  border-bottom: 0 !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-them.is-first {
  margin-bottom: calc(var(--plain-gap-within-group) + 2px) !important;
}
.msg-bubble-wrapper,
.msg-content-stack {
  overflow: visible;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before,
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  top: calc(100% - 1px);
  height: 12px;
  background-repeat: repeat-x;
  background-size: auto 71px;
  background-position: left -24px;
  pointer-events: none;
  z-index: 1;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/bluelace-dyhi6c.png");
}
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/pinklace-t2hrld.png");
}
.msg-plain-me.plain-last::after,
.msg-plain-me.plain-single::after {
  content: "";
  position: absolute;
  right: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/bluewing-ra1cz8.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: right center;
  animation: wing-sway 2s ease-in-out infinite;
}
.msg-plain-them.plain-first::after,
.msg-plain-them.plain-single::after {
  content: "";
  position: absolute;
  left: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/pinkwing-t1kiwd.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: left center;
  animation: wing-sway 2s ease-in-out infinite;
}
@keyframes wing-sway {
  0%, 100% { transform: translateY(-50%) rotate(6deg); }
  50%      { transform: translateY(-50%) rotate(-6deg); }
}
/* ----------2. avatars---------- */

[data-theme-style="plain"] .msg-avatar-them-container {
  visibility: hidden;
  pointer-events: none;
  position: relative;
}
[data-theme-style="plain"] .msg-avatar-me-container {
  visibility: hidden;
  pointer-events: none;
  position: relative;
  height: 0 !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

[data-theme-style="plain"] .msg-avatar-them-container.is-first,
[data-theme-style="plain"] .msg-avatar-them-container.is-single {
  visibility: visible;
  pointer-events: auto;
  align-self: flex-start !important;   /* ← 关键：锁定顶边为起点 */
  transform: translateY(-10px);         /* 想更错位就调这个数 */
}
[data-theme-style="plain"] .msg-avatar-me-container.is-last,
[data-theme-style="plain"] .msg-avatar-me-container.is-single {
  visibility: visible;
  pointer-events: auto;
  height: auto !important;
  align-self: flex-end !important;
  transform: translateY(20px);
}
[data-theme-style="plain"] .msg-avatar-them-container::before,
[data-theme-style="plain"] .msg-avatar-me-container::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: calc(100% + 2px);
  transform: translateX(calc(-50% - 1px));
  width: 22px;
  height: 12px;
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  pointer-events: none;
}
[data-theme-style="plain"] .msg-avatar-them-container::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/pinkring-mz8cuk.png");
}
[data-theme-style="plain"] .msg-avatar-me-container::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/bluering-pfjnqb.png");
}
.msg-avatar-them-ghost {
  pointer-events: none !important;
}
/* ----------3. read status---------- */
[data-theme-style="plain"] .msg-me.is-last .msg-status-custom,
[data-theme-style="plain"] .msg-me.is-single .msg-status-custom {
  margin-top: 12px !important;
}
.timestamp-custom {
  margin-bottom: 30px !important;
}
/* ----------4. thinking button---------- */
.nuo-thinking-wrap {
  width: max-content !important;
  max-width: none !important;
  transform: translateX(-2px) !important;
}
.nuo-thinking-btn {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
}
.nuo-thinking-arrow,
.nuo-thinking-icon {
  display: none !important;
}
.nuo-thinking-label {
  white-space: nowrap !important;
}
.nuo-thinking-label::before {
  content: "‎┈─┈˖˚⊹ ⋆ ";
}
.nuo-thinking-label::after {
  content: " ⋆ ⊹˚˖ ┈─┈";
}
/* ----------5. translation---------- */
.msg-translation-wrapper {
  display: contents !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
}
.msg-translation-content {
  display: none !important;
}
.msg-translation-btn {
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
  width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1.2 !important;
  opacity: 0.85 !important;
  pointer-events: auto !important;
}
.msg-translation-btn::before {
  content: "ʚ✞ɞ" !important;
  display: inline-flex !important;
  margin-right: 2px !important;
  color: currentColor !important;
  font-size: 11px !important;
  line-height: 1 !important;
}
.msg-translation-btn :is(svg, i, img, [data-icon], [aria-hidden="true"], [role="img"], .icon, .lucide, [class*="icon"]) {
  display: none !important;
}
.msg-plain-me .msg-translation-btn {
  position: absolute !important;
  top: calc(100% + 12px) !important;
  right: 8px !important;
  left: auto !important;
  z-index: 50 !important;
}
.msg-plain-them .msg-translation-btn {
  position: absolute !important;
  top: calc(100% + 12px) !important;
  left: -8px !important;
  right: auto !important;
  z-index: 50 !important;
}
.msg-plain-me.plain-first .msg-translation-btn,
.msg-plain-them.plain-first .msg-translation-btn {
  top: calc(100% + 20px) !important;
}
/* keep this order: collapsed 14 -> first collapsed 22 -> expanded 20 */
.msg-plain-me:has(.msg-translation-btn),
.msg-plain-them:has(.msg-translation-btn) {
  position: relative !important;
  overflow: visible !important;
  margin-bottom: 14px !important;
}
.msg-plain-me.plain-first:has(.msg-translation-btn),
.msg-plain-them.plain-first:has(.msg-translation-btn) {
  margin-bottom: 22px !important;
}
.msg-plain-me:has(.msg-translation-detached-content),
.msg-plain-them:has(.msg-translation-detached-content) {
  margin-bottom: 20px !important;
}
.msg-translation-detached {
  display: block !important;
  width: fit-content !important;
  max-width: var(--detached-max-width) !important;
  margin: 11px 0 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  overflow: visible !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.is-first .msg-translation-detached {
  margin-top: 18px !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-them.is-first:has(.msg-translation-detached-content) {
  margin-bottom: calc(var(--plain-gap-within-group) + 1px) !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-me.is-first:has(.msg-translation-detached-content) {
  margin-bottom: calc(var(--plain-gap-within-group) - 1px) !important;
}
.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-me { align-self: flex-end !important; }
.msg-translation-detached-content {
  display: inline-block !important;
  width: fit-content !important;
  max-width: var(--detached-max-width) !important;
  margin: 0 !important;
  border-radius: 0 !important;
  padding: 5px 10px !important;
  color: #3f3f3f !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  white-space: normal !important;
  overflow-wrap: anywhere !important;
  text-align: left !important;
}
.msg-me .msg-translation-detached-content {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
}
.msg-them .msg-translation-detached-content {
  background: rgba(240, 233, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
}
/* ----------6. voice---------- */
.voice-msg,
.voice-msg-me,
.voice-msg-them {
  display: flex !important;
  flex-direction: column !important;
  gap: 5px !important;
  background: none !important;
  border: none !important;
  position: static !important;
}
.voice-msg-me { align-items: flex-end !important; }
.voice-msg-them { align-items: flex-start !important; }
.msg-plain-me:has(.voice-msg),
.msg-plain-them:has(.voice-msg) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.msg-plain-me:has(.voice-msg)::before,
.msg-plain-them:has(.voice-msg)::before,
.msg-plain-me:has(.voice-msg)::after,
.msg-plain-them:has(.voice-msg)::after {
  content: none !important;
  display: none !important;
}
.voice-controls-row {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  width: fit-content !important;
  max-width: 100% !important;
  border-radius: 0 !important;
  padding: 7px 12px !important;
}
.msg-me .voice-controls-row {
  background: rgba(240, 233, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
}
.msg-them .voice-controls-row {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
}
.voice-play-btn,
.voice-download-btn {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.voice-transcription-toggle {
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
  width: max-content !important;
  max-width: none !important;
  white-space: nowrap !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  -webkit-mask: none !important;
  mask: none !important;
  padding: 2px 0 !important;
  color: #9a9aa5 !important;
  font-size: 11px !important;
  opacity: 0.85 !important;
  position: relative !important;
  z-index: 30 !important;
  margin-top: -1px !important;
}
.voice-transcription-toggle::before {
  content: "ㅤㅤ ʚ✞ɞ" !important;
  display: inline-flex !important;
  margin-right: 2px !important;
  color: currentColor !important;
  font-size: 12px !important;
  line-height: 1 !important;
}
.voice-transcription-toggle::after {
  content: none !important;
  display: none !important;
}
.voice-transcription-toggle :is(svg, i, img, [data-icon], [aria-hidden="true"], [role="img"], .icon, .lucide, [class*="icon"]) {
  display: none !important;
}
.voice-msg-me .voice-transcription-toggle { align-self: flex-end !important; }
.voice-msg-them .voice-transcription-toggle { align-self: flex-start !important; }
[data-theme-style="plain"] .msg-bubble-wrapper:has(.voice-transcription-toggle):not(:has(.voice-transcription)):not(:has(.voice-text-bar)) {
  margin-bottom: calc(var(--plain-gap-within-group) - 5px) !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.is-last:has(.voice-transcription-toggle):not(:has(.voice-transcription)):not(:has(.voice-text-bar)),
[data-theme-style="plain"] .msg-bubble-wrapper.is-single:has(.voice-transcription-toggle):not(:has(.voice-transcription)):not(:has(.voice-text-bar)) {
  margin-bottom: calc(var(--plain-gap-between-groups) - 5px) !important;
}
.voice-transcription,
.voice-text-bar {
  display: inline-block !important;
  width: fit-content !important;
  max-width: var(--detached-max-width) !important;
  margin-top: 1px !important;
  border-radius: 0 !important;
  padding: 5px 10px !important;
  color: #3f3f3f !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  white-space: normal !important;
  overflow-wrap: anywhere !important;
  text-align: left !important;
}
.msg-me .voice-transcription,
.msg-me .voice-text-bar {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  align-self: flex-end !important;
}
.msg-them .voice-transcription,
.msg-them .voice-text-bar {
  background: rgba(240, 233, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
  align-self: flex-start !important;
}
.msg-bubble-wrapper:has(.voice-transcription-toggle),
.msg-bubble-wrapper:has(.voice-transcription),
.msg-bubble-wrapper:has(.msg-translation-btn),
.msg-bubble-wrapper:has(.msg-translation-detached),
.msg-content-stack:has(.voice-transcription-toggle),
.msg-content-stack:has(.voice-transcription),
.msg-content-stack:has(.msg-translation-btn),
.msg-content-stack:has(.msg-translation-detached) {
  overflow: visible !important;
  z-index: 20 !important;
}
/* ----------7. reply---------- */
.msg-reply-block {
  display: none !important;
}
.msg-reply-block-detached {
  display: flex !important;
  flex-direction: row !important;
  align-items: stretch !important;
  column-gap: 0 !important;
  row-gap: 4px !important;
  flex-wrap: nowrap !important;  
  position: relative !important;
  order: -1 !important;
  width: var(--quote-rail-width) !important;
  max-width: var(--quote-rail-width) !important;
  margin: 5px 0 5px !important;
  padding: 0 0 10px !important;
  background: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
.msg-reply-detached-them {
  position: relative !important;
  transform: translateX(-52px) !important;
  justify-content: flex-end !important;
  width: var(--quote-rail-width) !important;
  left: 0 !important;
  right: auto !important;
  top: 4px !important;
  margin-left: var(--quote-side-offset) !important;
  margin-right: 0 !important;
  text-align: right !important;
}
.msg-reply-detached-me {
  position: relative !important;
  transform: translateX(52px) !important;
  justify-content: flex-start !important;
  width: var(--quote-rail-width) !important;
  left: 0 !important;
  right: auto !important;
  top: 4px !important;
  margin-right: var(--quote-side-offset) !important;
  margin-left: 0 !important;
  text-align: left !important;
}
.msg-reply-detached-name,
.msg-reply-detached-text,
.msg-reply-detached-media {
  display: inline-block !important;
  max-width: var(--detached-max-width) !important;
  flex: 0 1 auto !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  font-size: 12px !important;
  color: #3f3f3f !important;
  border-radius: 0 !important;
  position: relative !important;
}
.msg-reply-detached-name {
  display: inline-flex !important;
  align-items: flex-start !important;
  align-self: stretch !important;
  flex-shrink: 0 !important;             
  white-space: nowrap !important;
  padding: 5px 0 5px 8px !important;
  max-width: var(--reply-name-max) !important; 
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

.msg-reply-detached-me,
.msg-reply-detached-them {
  flex-wrap: nowrap !important;
}
.msg-reply-detached-text,
.msg-reply-detached-media {
  align-self: stretch !important;
  padding: 5px 8px 5px 3px !important;
}

.msg-reply-detached-text {
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  display: inline-block !important;
  min-width: 0 !important;
  max-width: var(--detached-max-width) !important;
  -webkit-mask: none !important;
  mask: none !important;
}
.msg-reply-detached-me .msg-reply-detached-name,
.msg-reply-detached-me .msg-reply-detached-text,
.msg-reply-detached-me .msg-reply-detached-media {
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.7) 2.5px, rgba(255, 255, 255, 0) 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(255, 255, 255, 0.7) 2.5px, rgba(255, 255, 255, 0) 2.6px) 8px 8px / 16px 16px repeat,
    rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
}
.msg-reply-detached-them .msg-reply-detached-name,
.msg-reply-detached-them .msg-reply-detached-text,
.msg-reply-detached-them .msg-reply-detached-media {
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.7) 2.5px, rgba(255, 255, 255, 0) 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(255, 255, 255, 0.7) 2.5px, rgba(255, 255, 255, 0) 2.6px) 8px 8px / 16px 16px repeat,
    rgba(240, 233, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
}
.msg-reply-detached-me .msg-reply-detached-name,
.msg-reply-detached-them .msg-reply-detached-name {
