  border-right: 8px solid #ffffff;
}
.msg-sim-card .msg-sim-text{
  font-family: "Noto Sans SC", sans-serif !important;
  font-size: 10.5px !important;
  font-weight: 320 !important;
  font-style: normal !important;
  line-height: 1.4 !important;
  color: #3f3f3f !important;
  -webkit-text-fill-color: #3f3f3f !important;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  position: relative;
  z-index: 1;

  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: baseline !important;
  justify-content: center !important;
  overflow: hidden !important;
}

.msg-sim-card .msg-sim-text::before{ content: "ʚ"; flex: 0 0 auto; margin-right: 3px; }
.msg-sim-card .msg-sim-text::after { content: "ɞ"; flex: 0 0 auto; margin-left: 3px; }

.msg-sim-card .msg-sim-text span{
  display: block;
  flex: 0 1 auto;
  min-width: 0;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: "Noto Sans SC", sans-serif !important;
  font-style: normal !important;
}

.msg-sim-card .msg-sim-text span::before,
.msg-sim-card .msg-sim-text span::after{ content: none !important; }
.msg-sim-card .msg-sim-divider{ display: none !important; }

/* ========== 补丁：subtext chip ========== */

/* 1. toggle 图标换成和翻译一样的颜文字 ʚ✞ɞ */
.msg-subtext-toggle {
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
  display: inline-flex !important;
  align-items: center !important;
  transform: none !important;
}
.msg-subtext-toggle svg { display: none !important; }
.msg-subtext-toggle::before {
  content: "ʚ✞ɞ" !important;
  color: #9a9aa5 !important;
  -webkit-text-fill-color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1 !important;
}

/* 2. 外层 chip：清背景/边框/阴影，不倾斜，放开宽度；上方留空 */
.msg-subtext-chip,
.msg-subtext-chip.is-me,
.msg-subtext-chip.is-open {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 16px !important;
  max-width: 250px !important;
  position: relative !important;     /* 给展开态的透明点击层做定位基准 */
}

/* 展开后：隐藏 toggle 图标 + 不占位；toggle 变成覆盖气泡的透明点击层 → 点气泡收起 */
.msg-subtext-toggle.is-open {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 5 !important;             /* 盖在气泡上方接收点击 */
  background: none !important;
  cursor: pointer !important;
}
.msg-subtext-toggle.is-open::before {
  content: "" !important;            /* 展开后不显示颜文字 */
}

/* 3. subtext 文字：去背景，边框保留，不倾斜，中灰字，放宽，蓝波点盖在文字上方 */
.msg-subtext-body {
  position: relative !important;
  box-sizing: border-box !important;
  background: none !important;
  border: 1px solid #ebe7eb !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 0px !important;
  padding: 3px 12px !important;
  min-width: 0px !important;
  max-width: none !important;
  font-size: 12px !important;
  color: #808080 !important;
  -webkit-text-fill-color: #808080 !important;
}
.msg-subtext-body::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 2 !important;
  background:
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 8px 8px / 16px 16px repeat !important;
}

.typing {
  display: inline-flex;
  align-items: center;
  background-color: rgba(234, 235, 241, 0.7);
  border: 1px solid #ebe7eb !important;
  border-radius: 18px;
  padding: 8px 14px;
}

/* dot 换成图片 */
.typing .dot,
.typing::after {
  content: "";
  display: inline-block;
  width: 10px;               /* 按需调整 */
  height: 10px;              /* 按需调整 */
  background-image: url("https://atnefallhmhz.vercel.app/f/subtext-zh7bvc.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
}

.nuo-typing-bubble {
  background-color: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  border-radius: 0 !important;
}

/* ============================================
    天使 蕾丝 小猫尖 by atne
    禁二传二改 自定义和适配调整在开头🤍标注
    仅适配素净
   ============================================ */
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@100..900&display=swap');

/* ----------🤍custom🤍---------- */
:root {
  /* id */
  --custom-id-text: "@id";

  /* 个签 */
  --custom-title-caption: " 我知这世界本如露水般短暂，然而，然而。 ";

  /* 占位符 */
  --custom-placeholder-text: "Send something…";

  /* 图片 reaction tag*/
  --img-tag-1: "🤍 520";
  --img-tag-2: "🪽 134";

/* user 引用条长度 */
  --reply-text-me-max: 200px; /* 引用条太长缩小 反之增大 */
}

/* ----------🤍end🤍---------- */

/* ----------variables---------- */
:root {
  --plain-avatar-size: 35px;
  --plain-avatar-radius: 50%;
  --plain-avatar-gap: 8px;
  --plain-content-max-width: 78%;
  --plain-gap-between-groups: 36px;
  --plain-gap-within-group: 16px;
  --plain-padding-right-them: 40px;
  --plain-padding-left-me: 40px;
  --detached-max-width: min(54vw, 260px);
  --reply-name-max: 160px;
  --reply-text-them-max: 220px;   
  --quote-side-offset: 7vw;
  --quote-rail-width: 80vw;
  --thinking-btn-bg: transparent;
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-color: #9a9aa5;
  --reply-bar-accent: rgb(227, 220, 224);
  --chat-header-avatar-size: 48px;
  --plus-btn-icon: url('https://atnefallhmhz.vercel.app/f/menuicon-0889qs.png');

}
/* ----------1. bubbles---------- */
.msg-plain {
  position: relative;
  z-index: 0;
  overflow: visible;
  border-radius: 0 !important;
  padding: 7px 12px 7px !important;
  color: #3f3f3f !important;
}
.msg-plain-me {
  background: rgba(240, 234, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
  color: #3f3f3f !important;
}
.msg-plain-them {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  color: #3f3f3f !important;
}
.msg-plain-me.plain-last,
.msg-plain-me.plain-single,
.msg-plain-them.plain-first,
.msg-plain-them.plain-single {
  border-bottom: 0 !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-them.is-first {
  margin-bottom: calc(var(--plain-gap-within-group) + 2px) !important;
}
.msg-bubble-wrapper,
.msg-content-stack {
  overflow: visible;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before,
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  top: calc(100% - 1px);
  height: 12px;
  background-repeat: repeat-x;
  background-size: auto 71px;
  background-position: left -24px;
  pointer-events: none;
  z-index: 1;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/bluelace-dyhi6c.png");
}
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/pinklace-t2hrld.png");
}
.msg-plain-me.plain-last::after,
.msg-plain-me.plain-single::after {
  content: "";
  position: absolute;
  right: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/bluewing-ra1cz8.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: right center;
  animation: wing-sway 2s ease-in-out infinite;
}
.msg-plain-them.plain-first::after,
.msg-plain-them.plain-single::after {
  content: "";
  position: absolute;
  left: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/pinkwing-t1kiwd.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: left center;
  animation: wing-sway 2s ease-in-out infinite;
}
@keyframes wing-sway {
  0%, 100% { transform: translateY(-50%) rotate(6deg); }
  50%      { transform: translateY(-50%) rotate(-6deg); }
}
/* ----------2. avatars---------- */

[data-theme-style="plain"] .msg-avatar-them-container {
  visibility: hidden;
  pointer-events: none;
  position: relative;
}
[data-theme-style="plain"] .msg-avatar-me-container {
  visibility: hidden;
