[data-theme-style="plain"] .msg-bubble-wrapper.is-last:has(.voice-transcription-toggle):not(:has(.voice-transcription)):not(:has(.voice-text-bar)),
[data-theme-style="plain"] .msg-bubble-wrapper.is-single:has(.voice-transcription-toggle):not(:has(.voice-transcription)):not(:has(.voice-text-bar)) {
