}
.msg-sim-card > .msg-sim-texture::after,
.msg-sim-card > .msg-sim-loc-tag::after,
.msg-sim-card > .msg-sim-date::after{
  content: "";
  flex: 0 0 auto;
  width: 13px;
  height: 13px;
