  -webkit-text-fill-color: #3f3f3f;
}
.msg-sim-card > .msg-sim-texture::after{
  background-image: url("https://atnefallhmhz.vercel.app/f/image-3j6a57.png");
}
.msg-sim-card > .msg-sim-loc-tag{ order: 2; }
.msg-sim-card > .msg-sim-loc-tag > div{ display: none !important; }
.msg-sim-card > .msg-sim-loc-tag::after{
  background-image: url("https://atnefallhmhz.vercel.app/f/location-f8utfy.png");
}
.msg-sim-card > .msg-sim-date{
  order: 3;
  border-bottom: none !important;
  border-bottom-left-radius: 8px !important;
  border-bottom-right-radius: 8px !important;
}
.msg-sim-card > .msg-sim-date::after{
  background-image: url("https://atnefallhmhz.vercel.app/f/time-5uqki3.png");
}
.msg-sim-card > div:nth-child(3){
  order: 4;
  position: relative !important;
  width: auto !important;
  max-width: 90% !important;
  align-self: flex-end;
  margin-top: 14px !important;
  padding: 13px 18px !important;
  background: #ffffff !important;
  border: 1px solid #E2E7EB !important;
  border-radius: 8px !important;
  box-shadow: none !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
}
.msg-sim-card > div:nth-child(3)::before{
  content: "";
  position: absolute;
  right: -8px;
  bottom: 6px;
  width: 0; height: 0;
  border-left: 8px solid #E2E7EB;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
}
.msg-sim-card > div:nth-child(3)::after{
  content: "";
  position: absolute;
  right: -7px;
  bottom: 6px;
  width: 0; height: 0;
  border-left: 8px solid #ffffff;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
}

.msg-them .msg-sim-card > div:nth-child(3){
  align-self: flex-start !important;
}
.msg-them .msg-sim-card > div:nth-child(3)::before{
  left: -8px; right: auto;
  border-left: 0;
  border-right: 8px solid #E2E7EB;
}
.msg-them .msg-sim-card > div:nth-child(3)::after{
  left: -7px; right: auto;
  border-left: 0;
  border-right: 8px solid #ffffff;
}
.msg-sim-card .msg-sim-text{
  font-family: "Noto Sans SC", sans-serif !important;
  font-size: 10.5px !important;
  font-weight: 320 !important;
  font-style: normal !important;
  line-height: 1.4 !important;
  color: #3f3f3f !important;
  -webkit-text-fill-color: #3f3f3f !important;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  position: relative;
  z-index: 1;

  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: baseline !important;
  justify-content: center !important;
  overflow: hidden !important;
}

.msg-sim-card .msg-sim-text::before{ content: "ʚ"; flex: 0 0 auto; margin-right: 3px; }
.msg-sim-card .msg-sim-text::after { content: "ɞ"; flex: 0 0 auto; margin-left: 3px; }

.msg-sim-card .msg-sim-text span{
  display: block;
  flex: 0 1 auto;
  min-width: 0;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: "Noto Sans SC", sans-serif !important;
  font-style: normal !important;
}

.msg-sim-card .msg-sim-text span::before,
.msg-sim-card .msg-sim-text span::after{ content: none !important; }
.msg-sim-card .msg-sim-divider{ display: none !important; }

/* ========== 补丁：subtext chip ========== */

/* 1. toggle 图标换成和翻译一样的颜文字 ʚ✞ɞ */
.msg-subtext-toggle {
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
  display: inline-flex !important;
  align-items: center !important;
  transform: none !important;
}
.msg-subtext-toggle svg { display: none !important; }
.msg-subtext-toggle::before {
  content: "ʚ✞ɞ" !important;
  color: #9a9aa5 !important;
  -webkit-text-fill-color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1 !important;
}

/* 2. 外层 chip：清背景/边框/阴影，不倾斜，放开宽度；上方留空 */
.msg-subtext-chip,
.msg-subtext-chip.is-me,
.msg-subtext-chip.is-open {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 16px !important;
  max-width: 250px !important;
  position: relative !important;     /* 给展开态的透明点击层做定位基准 */
}

/* 展开后：隐藏 toggle 图标 + 不占位；toggle 变成覆盖气泡的透明点击层 → 点气泡收起 */
.msg-subtext-toggle.is-open {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 5 !important;             /* 盖在气泡上方接收点击 */
  background: none !important;
  cursor: pointer !important;
}
.msg-subtext-toggle.is-open::before {
  content: "" !important;            /* 展开后不显示颜文字 */
}

/* 3. subtext 文字：去背景，边框保留，不倾斜，中灰字，放宽，蓝波点盖在文字上方 */
.msg-subtext-body {
  position: relative !important;
  box-sizing: border-box !important;
  background: none !important;
  border: 1px solid #ebe7eb !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 0px !important;
  padding: 3px 12px !important;
  min-width: 0px !important;
  max-width: none !important;
  font-size: 12px !important;
  color: #808080 !important;
  -webkit-text-fill-color: #808080 !important;
}
.msg-subtext-body::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 2 !important;
  background:
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 8px 8px / 16px 16px repeat !important;
}

.typing {
  display: inline-flex;
  align-items: center;
  background-color: rgba(234, 235, 241, 0.7);
  border: 1px solid #ebe7eb !important;
  border-radius: 18px;
  padding: 8px 14px;
}

/* dot 换成图片 */
.typing .dot,
.typing::after {
  content: "";
  display: inline-block;
  width: 10px;               /* 按需调整 */
  height: 10px;              /* 按需调整 */
  background-image: url("https://atnefallhmhz.vercel.app/f/subtext-zh7bvc.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
}

.nuo-typing-bubble {
  background-color: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  border-radius: 0 !important;
}

:root {
  /* ==========================================
     我方气泡 
  ========================================== */
  --bubble-me-bg: #DEE8F4;               /* 变更为烟雨蓝 */
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #354454;            /* 文字适配为曜石蓝灰 */
  --bubble-me-border: none;
  --bubble-me-shadow: 0 1px 3px rgba(107, 125, 143, 0.12);
  --bubble-me-link-color: #6B7D8F;       

  /* 1. 缩小整体与高度 */
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.35;
  --bubble-me-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-me-radius: 12px;
  --bubble-me-radius-first: 12px 12px 4px 12px;
  --bubble-me-radius-mid: 12px 4px 4px 12px;
  --bubble-me-radius-last: 12px 4px 12px 12px;

  /* ==========================================
     对方气泡 (白色、雨丝蓝灰边框、缩小、方圆)
  ========================================== */
  --bubble-them-bg: #FFFFFF;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #354454;          
  --bubble-them-border: 1px solid #E2EAF2; /* 边框变极浅雨丝蓝灰 */
  --bubble-them-shadow: 0 1px 2px rgba(107, 125, 143, 0.08);
  --bubble-them-link-color: #6B7D8F;

  /* 1. 缩小整体与高度 */
  --bubble-them-font-size: 14px;
  --bubble-them-line-height: 1.35;
  --bubble-them-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-them-radius: 12px;
  --bubble-them-radius-first: 12px 12px 12px 4px;
  --bubble-them-radius-mid: 4px 12px 12px 4px;
  --bubble-them-radius-last: 4px 12px 12px 12px;

  /* ==========================================
     相关组件同步缩小与适配
  ========================================== */
  --translation-btn-color: #6B7D8F;
  --translation-text-color: #4A5B6E;
  --translation-bg: rgba(222, 232, 244, 0.4);
  --translation-size: 12.5px;
  --translation-padding: 6px 10px;

  --voice-me-color: #354454;             /* 我方语音图标 */
  --voice-me-bar-active: #354454;        /* 我方波形 */
  --voice-me-bar-inactive: rgba(53, 68, 84, 0.15);
  --voice-them-color: #354454;           /* 对方语音图标 */
  --voice-them-bar-active: #6B7D8F;      /* 对方波形 */
  --voice-them-bar-inactive: #E2EAF2;

  --plain-avatar-radius: 12px;
  --avatar-radius: 12px;
}

/* ==========================================
   一、头像显示逻辑 (隐藏时保留占位，气泡完美对齐)
========================================== */
.msg-avatar-me-container {
  visibility: hidden !important;
}
.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  visibility: visible !important;
}

.msg-avatar-them-container {
  visibility: hidden !important;
}
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* ==========================================
   二、【我方头像】对齐与上下左右微调
========================================== */
.msg-avatar-me-container {
  align-self: flex-end !important;
  position: relative !important;
  left: -30px !important;
  top: 40px !important;
  margin-left: 10px !important; 
  overflow: visible !important;          
}

/* ==========================================
   三、【对方头像】对齐与上下左右微调
========================================== */
.msg-avatar-them-container {
  position: relative !important;
  left: 30px !important;
  top: -40px !important;
  margin-right: 10px !important;
  overflow: visible !important;          
}

/* ==========================================
   四、双方消息间距调整 (换人发言时较宽)
========================================= */
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single {
  margin-bottom: 30px !important; 
}

/* ==========================================
   五、头像：方圆形 + 白色边框 + 可旋转超大双层底框 (双层独立阴影)
========================================== */
.msg-avatar-me-inner,
.msg-avatar-them-inner,
.msg-avatar-custom {
  border-radius: 12px !important;
  border: 2px solid #FFFFFF !important;    
  box-shadow: 0 2px 6px rgba(107, 125, 143, 0.15) !important; 
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 3 !important;                   
}

.msg-avatar-me-container::before,
.msg-avatar-them-container::before {
  content: "";
  position: absolute;
  top: -1px !important;
  left: -1px !important;
  right: -1px !important;
  bottom: -1px !important;

  border-radius: 14px !important;          
  background: #FFFFFF !important;          
  border: 1px solid #EBF1F7 !important;    
  box-shadow: 0 4px 10px rgba(107, 125, 143, 0.12) !important; 

  z-index: 1 !important;                   
  pointer-events: none !important;
  transform: translateY(-3px) translateX(-3px) rotate(-10deg) !important;     
}

/* ==========================================
   六、对方消息左侧：贯穿竖线与圆点 (灰羽蓝)
========================================== */
.msg-avatar-them-container::after,
.msg-bubble-wrapper.msg-them::after {
  display: none !important;
  background: none !important;
}

.msg-bubble-wrapper.msg-them::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            
  transform: translateX(-50%) !important; 
  left: 20px !important; 
}

.msg-bubble-wrapper.msg-them.is-first::before {
  top: -15px !important;             
  bottom: -35px !important; 
  background: linear-gradient(#A9B8C6, #A9B8C6) no-repeat center top !important; /* 线条变灰羽蓝 */
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-them.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 
  background: linear-gradient(#A9B8C6, #A9B8C6) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-them.is-last::before {
  top: -20px !important; 
  bottom: 10px !important;           
  background: 
    radial-gradient(circle, #A9B8C6 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#A9B8C6, #A9B8C6) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

.msg-bubble-wrapper.msg-them.is-single::before {
  top: -15px !important;             
  bottom: 10px !important; 
  background: 
    radial-gradient(circle, #A9B8C6 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#A9B8C6, #A9B8C6) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

/* ==========================================
   七、我方消息右侧：贯穿竖线与顶部圆点 (灰羽蓝)
========================================= */
.msg-avatar-me-container::after,
.msg-bubble-wrapper.msg-me::after {
  display: none !important;
  background: none !important;
}

.msg-bubble-wrapper.msg-me::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            
  transform: translateX(50%) !important;  
  right: 20px !important; 
}

.msg-bubble-wrapper.msg-me.is-first::before {
  top: 10px !important;             
  bottom: -50px !important;          
  background: 
    radial-gradient(circle, #A9B8C6 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#A9B8C6, #A9B8C6) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; 
}

.msg-bubble-wrapper.msg-me.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 
  background: linear-gradient(#A9B8C6, #A9B8C6) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-me.is-last::before {
  top: -20px !important; 
  bottom: 30px !important;           
  background: linear-gradient(#A9B8C6, #A9B8C6) no-repeat center top !important;
  background-size: 2px 100% !important;
}

.msg-bubble-wrapper.msg-me.is-single::before {
