/* ==========================================
   二十五、终极消除重叠：头像移位空间补偿 (仅新增)
========================================== */

/* 
   💡 核心原理：
   1. 对方头像往上飞了 40px，我们就在对方消息的头部顶开 42px 的安全空间，让头像刚好落在这个空档里，绝不挡住上方的旁白！
   2. 我方头像往下掉了 40px，我们就在我方消息的底部留出 42px 的安全空间，防止掉下去的头像压住下方的消息！
*/

/* 1. 【对方消息】：给头部顶开空间，完美接住往上飞的头像和文字 */
.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-single {
  /* ▼ 这里的 42px 必须与您给对方头像设的 top: -40px 大小相匹配（这里设为 42px 完美顶开） */
  margin-top: 40px !important; 
}

/* 2. 【我方消息】：给底部留出空间，完美容纳往下掉的头像 */
.msg-bubble-wrapper.msg-me.is-last,
.msg-bubble-wrapper.msg-me.is-single {
  /* ▼ 这里的 42px 必须与您给我方头像设的 top: 40px 大小相匹配 */
  margin-bottom: 40px !important; 
}

/* 3. 【顶栏安全边距】：防止第一条消息直接钻到顶栏悬挂的那个大圆形头像后面 */
.chat-messages-area, 
.chat-message-list-custom {
  padding-top: 30px !important;
}
/* ==============================================================
   ★ iOS 灵动岛 / 刘海屏 顶部自动防挡适配 ★
============================================================== */

/* 1. 自动给顶栏增加系统反馈的安全区域高度 */
:root {
  --chat-header-height: calc(56px + env(safe-area-inset-top, 0px)) !important;
}

/* 2. 在顶栏内部用内边距将所有按钮往下推，避开灵动岛 */
.chat-header-custom {
  padding-top: env(safe-area-inset-top, 0px) !important;
  box-sizing: border-box !important;
}

/* 3. 精准数学修正：由于总高度增加了，原本的绝对居中会有点偏下。
      这个计算公式能保证你的昵称不管在灵动岛还是普通手机，都能在“可用区域”完美居中 */
.header-profile-section {
  top: calc(50% + (env(safe-area-inset-top, 0px) / 2)) !important;
}

/*⁣​‌⁠‌‌‌​​​‌‍‌​​⁠‍​‌⁠⁠​⁠⁠‌​⁠‍⁠​⁠​​‌⁠‍‌‍⁠​​⁠‍‍‍⁠‌‍‌⁠‌⁠​‍⁠‍⁠​​‍‌​​‍​⁣ ========================================================
   Apple Music 高仿真最终完美版
   ======================================================== */

:root {
    /* 1. 经典 Apple Music 尺寸比例 */
    --rp-disc-size: 350px;
    --rp-disc-radius: 20px;
    --rp-disc-bg: transparent;
    --rp-cover-size: 350px;
    --rp-cover-radius: 20px;

    /* 2. 细进度条 */
    --rp-scrubber-height: 7px;
    --rp-scrubber-radius: 999px;
    --rp-scrubber-bg: rgba(255, 255, 255, 0.18);
    --rp-scrubber-fill: rgba(255, 255, 255, 0.7);
    --rp-scrubber-thumb: transparent;
}

/* 3. 顶部横条 */
.rp-header {
    position: relative !important;
}
.rp-header::after {
    content: "" !important;
    position: absolute !important;
    top: 150px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    width: 56px !important;
    height: 4px !important;
    background: rgba(255, 255, 255, 0.4) !important;
    border-radius: 100px !important;
    pointer-events: none !important;
}

/* 4. 封面居中与上提 */
.rp-stage {
    margin-top: -200px !important;
    position: relative !important;
}
.vinyl-disc {
    position: relative !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    border: none !important;
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45) !important;
    animation: none !important;
    margin: 0 !important;
}
.circular-img { box-shadow: none !important; }
.tonearm-container { display: none !important; }
.lt-avatars-section { display: none !important; }

/* 5. 背景光晕氛围 + 隐藏页面切换小圆点 */
.bg-img {
    filter: blur(55px) saturate(160%) brightness(0.65) !important;
    transform: scale(1.2) !important;
}
.bg-overlay {
    background: radial-gradient(circle at 50% 30%, rgba(255,255,255,0.06) 0%, rgba(0,0,0,0.55) 100%) !important;
}
/* 彻底隐藏封面正下方的小圆点 */
.rp-dots, .rp-indicator, .swiper-pagination, .slick-dots,
div[class*="dot"], div[class*="indicator"], div[class*="pagination"] {
    display: none !important;
}

/* 6. 歌名与歌手（小箭头消失 + 播放条自然下移拉开间隙） */
.rp-song-title {
    font-size: 22px !important;
    font-weight: 700 !important;
    color: #ffffff !important;
}
.rp-song-artist {
    font-size: 16px !important;
    color: rgba(255, 255, 255, 0.55) !important;
    display: inline-block !important;
}
.rp-song-artist + *,
.rp-song-artist ~ svg,
.rp-song-artist::after {
    display: none !important;
}
.rp-now-playing, .rp-sleep, .rp-lyric { display: none !important; }

/* 播放条组件整体下移，撑开与歌手名的呼吸感 */
.scrubber-track, .rp-time-row {
    transform: translateY(18px) !important;
}

/* 7. 播放条与时间行稍微往上抬 */
.scrubber-track, .rp-time-row {
    transform: translateY(2px) !important;
}
.scrubber-track {
    margin-top: 0 !important;
}

/* 8. 右侧按钮：星星与三个点（加大加粗） */
.rp-btn-fav, .rp-btn-add {
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: 24px 24px !important;     /* 从 20px 放大到 24px */
    opacity: 0.9 !important;
}
.rp-btn-fav svg, .rp-btn-add svg, .rp-btn-share svg { opacity: 0 !important; }

/* 五角星：加粗加大 */
.rp-btn-fav {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><polygon points='12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'/></svg>") !important;
}

/* 三个点：加大圆点尺寸 */
.rp-btn-add {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='white'><circle cx='4.5' cy='12' r='2.3'/><circle cx='12' cy='12' r='2.3'/><circle cx='19.5' cy='12' r='2.3'/></svg>") !important;
}

.rp-btn-share {
    display: none !important;
}

/* 9. 进度条时间行 + 完美 Dolby Atmos 徽标 */
.rp-time-row {
    position: relative !important;
    font-size: 12px !important;
    color: rgba(255, 255, 255, 0.45) !important;
    font-variant-numeric: tabular-nums !important;
}
.rp-time-row::after {
    content: "" !important;
    position: absolute !important;
    left: 50% !important;
    top: 54% !important;
    transform: translate(-50%, -50%) !important;
    width: 112px !important;
    height: 18px !important;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='112' height='18' viewBox='0 0 112 18'><path d='M0 3h3.4c2.6 0 4.2 2.3 4.2 5.4s-1.6 5.4-4.2 5.4H0V3zm16.4 0h-3.4c-2.6 0-4.2 2.3-4.2 5.4s1.6 5.4 4.2 5.4h3.4V3z' fill='rgba(255,255,255,0.42)'/><text x='22' y='12.5' fill='rgba(255,255,255,0.42)' font-size='14.5' font-weight='600' font-family='-apple-system,BlinkMacSystemFont,SF Pro Text,sans-serif' letter-spacing='0.2'>Dolby Atmos</text></svg>") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
}

/* 10. 播放按钮：双三角快退 / 快进 */
.rp-btn-prev, .rp-btn-next {
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: 26px 18px !important;
}
.rp-btn-prev svg, .rp-btn-next svg { opacity: 0 !important; }
.rp-btn-prev {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 16'><path d='M10.8 1.5 L2.2 7.2 C1.2 7.8 1.2 8.2 2.2 8.8 L10.8 14.5 C11.8 15.2 12.5 14.7 12.5 13.5 L12.5 2.5 C12.5 1.3 11.8 0.8 10.8 1.5 Z M21.8 1.5 L13.2 7.2 C12.2 7.8 12.2 8.2 13.2 8.8 L21.8 14.5 C22.8 15.2 23.5 14.7 23.5 13.5 L23.5 2.5 C23.5 1.3 22.8 0.8 21.8 1.5 Z' fill='%23ffffff' stroke='%23ffffff' stroke-width='1.2' stroke-linejoin='round'/></svg>") !important;
}
.rp-btn-next {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 16'><path d='M1.7 1.5 L10.3 7.2 C11.3 7.8 11.3 8.2 10.3 8.8 L1.7 14.5 C0.7 15.2 0 14.7 0 13.5 L0 2.5 C0 1.3 0.7 0.8 1.7 1.5 Z M12.7 1.5 L21.3 7.2 C22.3 7.8 22.3 8.2 21.3 8.8 L12.7 14.5 C11.7 15.2 11 14.7 11 13.5 L11 2.5 C11 1.3 11.7 0.8 12.7 1.5 Z' fill='%23ffffff' stroke='%23ffffff' stroke-width='1.2' stroke-linejoin='round'/></svg>") !important;
}

.rp-btn-play { transform: scale(1.2) !important; }
.rp-btn-play svg { color: #ffffff !important; fill: #ffffff !important; }

/* 11. 底部左右功能键：原生 Apple Music 质感 */
.rp-btn-repeat, .rp-btn-list {
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: 24px 24px !important;
    opacity: 0.75 !important;
}
.rp-btn-repeat svg, .rp-btn-list svg { opacity: 0 !important; }

/* 左下角：气泡居中圆尾 + 饱满圆润逗号 */
.rp-btn-repeat {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none'><path d='M19 14.5C19 16.4 17.4 18 15.5 18H9.8L7.2 20.8C6.6 21.4 5.5 21 5.5 20.1V18C4.1 18 3 16.9 3 15.5V6.5C3 4.6 4.6 3 6.5 3h11C18.4 3 20 4.6 20 6.5v8z' stroke='white' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round'/><path d='M8 8.5a1.5 1.5 0 0 1 1.5-1.5h.3v2c0 1.5-.8 2.2-1.8 2.5l-.2-.5c.6-.2 1-.6 1-1.2H8.5A1.5 1.5 0 0 1 8 8.5zm5 0a1.5 1.5 0 0 1 1.5-1.5h.3v2c0 1.5-.8 2.2-1.8 2.5l-.2-.5c.6-.2 1-.6 1-1.2h-.3A1.5 1.5 0 0 1 13 8.5z' fill='white'/></svg>") !important;
}

/* 右下角：疏松长方形列表（圆点变小、长横线、大行距） */
.rp-btn-list {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 26 20' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='round'><circle cx='3' cy='4' r='1.1' fill='white'/><line x1='7.5' y1='4' x2='24' y2='4'/><circle cx='3' cy='10' r='1.1' fill='white'/><line x1='7.5' y1='10' x2='24' y2='10'/><circle cx='3' cy='16' r='1.1' fill='white'/><line x1='7.5' y1='16' x2='24' y2='16'/></svg>") !important;
}

/*⁣​‌⁠‌‌‌​​​‌‍‌​​⁠‍​‌⁠⁠​⁠⁠‌​⁠‍⁠​⁠​​‌⁠‍‌‍⁠​​⁠‍‍‍⁠‌‍‌⁠‌⁠​‍⁠‍⁠​​‍‌​​‍​⁣ =====================================================
   ◻ 银色 iPod Classic · 糯叽机播放器皮肤
   参考：灰渐变背景 + 银色 iPod + 屏幕里的 Pause / Now Playing 标题栏 + 封面倒影
   .vinyl-disc   → 银色 iPod 素材（已内嵌，已裁边，MUSIC 改成 MENU）
   ::before      → 屏幕（细黑框 + 灰色标题栏 + 状态图标）
   ::after       → 机身表面的一层静态高光
   .circular-img → 屏幕里的专辑封面（带倒影）
   ===================================================== */

/* ---------- 0. 变量 ---------- */
:root {
  --rp-disc-size: 208px;
  --rp-disc-bg: transparent;
  --rp-disc-radius: 0px;
  --rp-cover-size: 80px;
  --rp-cover-radius: 2px;

  /* 进度条：细白线 + 白色圆点 */
  --rp-scrubber-height: 2px;
  --rp-scrubber-radius: 999px;
  --rp-scrubber-bg: rgba(255, 255, 255, 0.32);
  --rp-scrubber-fill: rgba(255, 255, 255, 0.95);
  --rp-scrubber-thumb: #ffffff;

  /* 装饰层 1：iPod 后面一圈柔和的亮光 */
  --rp-deco-1-image: radial-gradient(ellipse at 50% 38%, rgba(255, 255, 255, 0.38), transparent 62%);
  --rp-deco-1-top: 0;
  --rp-deco-1-left: 0;
  --rp-deco-1-width: 100%;
  --rp-deco-1-height: 100%;
  --rp-deco-1-size: 100% 100%;
  --rp-deco-1-z: 1;
}

/* ---------- 1. 背景：浅灰 → 深灰渐变 ---------- */
.bg-img {
  opacity: 0 !important;
}
.bg-overlay {
  background: linear-gradient(180deg,
    #aaabaf 0%,
    #97989d 42%,
    #76777d 100%) !important;
}

/* ---------- 2. 顶栏 ---------- */
.rp-header-title {
  color: rgba(255, 255, 255, 0.92) !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  letter-spacing: 0.5px !important;
}
.rp-btn-back,
.rp-btn-back svg,
.rp-btn-back svg * {
  color: rgba(255, 255, 255, 0.9) !important;
  stroke: rgba(255, 255, 255, 0.9) !important;
}

/* ---------- 3. iPod 机身 ---------- */
.tonearm-container {
  display: none !important;
}

.vinyl-disc {
  box-sizing: border-box !important;
  position: relative !important;
  isolation: isolate !important;
  width: 208px !important;
  height: 330px !important;
  border: none !important;
  border-radius: 0 !important;
  animation: none !important;
  transform: none !important;
  overflow: visible !important;
  background-color: transparent !important;
  background-image: url("data:image/webp;base64,") !important;
  background-size: 100% 100% !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  box-shadow: none !important;
  filter:
    drop-shadow(0 1px 0 rgba(255, 255, 255, 0.5))
    drop-shadow(0 20px 18px rgba(30, 32, 40, 0.38)) !important;
  -webkit-box-reflect: below 3px linear-gradient(transparent 82%, rgba(255, 255, 255, 0.2));
}

/* 屏幕：细黑框 + 灰色标题栏 + 白色内容区（盖住素材里粗黑框） */
.vinyl-disc::before {
  content: "Pause" !important;
  display: block !important;
  position: absolute !important;
  left: 5.5% !important;
  right: 5.3% !important;
  top: 3.6% !important;
  bottom: auto !important;
  width: auto !important;
  height: 45.2% !important;
  margin: 0 !important;
  box-sizing: border-box !important;
  padding: 3px 0 0 9px !important;
  border: 2px solid #2b3140 !important;
  border-radius: 6px !important;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.75),
    inset 0 0 0 1px rgba(255, 255, 255, 0.35) !important;
  transform: none !important;
  animation: none !important;
  opacity: 1 !important;
  filter: none !important;
  mix-blend-mode: normal !important;
  -webkit-mask: none !important;
  mask: none !important;
  clip-path: none !important;
  text-align: left !important;
  font: 700 11px/16px "Helvetica Neue", Helvetica, Arial, sans-serif !important;
  letter-spacing: 0 !important;
  color: #14171c !important;
  background-color: #ffffff !important;
  background-origin: border-box !important;
  background-repeat: no-repeat !important;
  background-size: 38px 11px, 100% 100% !important;
  background-position: right 8px top 7px, 0 0 !important;
  /* 暂停：蓝色暂停条 + 电池 */
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 38 11'><rect x='1' y='0' width='3.2' height='11' fill='%232a8bf2'/><rect x='6.4' y='0' width='3.2' height='11' fill='%232a8bf2'/><rect x='16' y='1' width='19' height='9' rx='2' fill='%2341c15a' stroke='%23666' stroke-width='0.8'/><rect x='35' y='3.5' width='2' height='4' fill='%23666'/></svg>"),
    linear-gradient(180deg, #e9ecee 0, #cdd3d7 11px, #b4bbc0 26px, #8b9197 26px, #8b9197 27px, #ffffff 27px, #ffffff 100%) !important;
  z-index: 1 !important;
}
.is-playing .vinyl-disc::before {
  content: "Now Playing" !important;
  /* 播放：蓝色播放三角 + 电池 */
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 38 11'><path d='M1 0l9 5.5-9 5.5z' fill='%232a8bf2'/><rect x='16' y='1' width='19' height='9' rx='2' fill='%2341c15a' stroke='%23666' stroke-width='0.8'/><rect x='35' y='3.5' width='2' height='4' fill='%23666'/></svg>"),
    linear-gradient(180deg, #e9ecee 0, #cdd3d7 11px, #b4bbc0 26px, #8b9197 26px, #8b9197 27px, #ffffff 27px, #ffffff 100%) !important;
}

/* 机身高光：一层很淡的静态光泽，让银色更有金属感 */
.vinyl-disc::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  top: 0 !important;
  bottom: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 14px !important;
  box-shadow: none !important;
  transform: none !important;
  animation: none !important;
  opacity: 1 !important;
  filter: none !important;
  pointer-events: none !important;
  background-color: transparent !important;
  background-image: linear-gradient(118deg,
    rgba(255, 255, 255, 0.55) 0%,
    rgba(255, 255, 255, 0) 28%,
    rgba(255, 255, 255, 0) 70%,
    rgba(0, 0, 0, 0.06) 100%) !important;
  background-size: 100% 100% !important;
  background-position: 0 0 !important;
  background-repeat: no-repeat !important;
  z-index: 4 !important;
}

/* 封面：放进屏幕，带倒影 */
.circular-img {
  position: absolute !important;
  top: 48px !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  margin: 0 0 0 -42px !important;
  width: 84px !important;
  height: 84px !important;
  border-radius: 2px !important;
  animation: none !important;
  /* Cover Flow 斜放：整张向后倾，一侧变窄，倒影跟着一起斜 */
  transform: perspective(300px) rotateY(36deg) !important;
  transform-origin: 50% 50% !important;
  filter: none !important;
  mix-blend-mode: normal !important;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.28), 0 0 0 1px rgba(0, 0, 0, 0.08) !important;
  -webkit-box-reflect: below 1px linear-gradient(transparent 62%, rgba(255, 255, 255, 0.5));
  z-index: 3 !important;
}
.circular-img::before,
.circular-img::after {
  display: none !important;
}

/* ---------- 4. 歌名 / 歌手 / 歌词 ---------- */
.rp-song-title {
  color: rgba(255, 255, 255, 0.95) !important;
  font-size: 22px !important;
  font-weight: 500 !important;
  letter-spacing: 0.2px !important;
  text-shadow: none !important;
}
.rp-song-artist {
  color: rgba(255, 255, 255, 0.58) !important;
  font-size: 15px !important;
  font-weight: 400 !important;
  letter-spacing: 0.2px !important;
  opacity: 1 !important;
}
.rp-now-playing {
  color: rgba(255, 255, 255, 0.5) !important;
  font-size: 12px !important;
}
.rp-lyric {
  color: rgba(255, 255, 255, 0.88) !important;
  font-weight: 400 !important;
  letter-spacing: 1px !important;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.18) !important;
}

/* ---------- 5. 睡眠计时 ---------- */
.rp-sleep,
.rp-sleep * {
  color: rgba(255, 255, 255, 0.55) !important;
  stroke: rgba(255, 255, 255, 0.55) !important;
}

/* ---------- 6. 收藏 / 加入歌单 / 分享 / 评论 ---------- */
.rp-quick-actions svg,
.rp-quick-actions svg * {
  stroke: rgba(255, 255, 255, 0.9) !important;
  color: rgba(255, 255, 255, 0.9) !important;
}
.rp-btn-fav svg,
.rp-btn-fav svg * {
  stroke: #ff3b3b !important;
  color: #ff3b3b !important;
}

/* ---------- 7. 进度条与时间 ---------- */
.scrubber-thumb {
  background: #ffffff !important;
  border: none !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3) !important;
}
.rp-time-row {
  color: rgba(255, 255, 255, 0.5) !important;
  font-size: 12px !important;
  letter-spacing: 0.3px !important;
  font-variant-numeric: tabular-nums !important;
}

/* ---------- 8. 控制栏 ---------- */
.rp-btn-prev svg,
.rp-btn-prev svg *,
.rp-btn-next svg,
.rp-btn-next svg *,
.rp-btn-play svg,
.rp-btn-play svg * {
  fill: rgba(255, 255, 255, 0.95) !important;
  color: rgba(255, 255, 255, 0.95) !important;
}
.rp-btn-repeat svg,
.rp-btn-repeat svg *,
.rp-btn-list svg,
.rp-btn-list svg * {
  stroke: rgba(255, 255, 255, 0.9) !important;
  color: rgba(255, 255, 255, 0.9) !important;
}
.rp-btn-play {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* ---------- 9. 一起听 ---------- */
.lt-avatar-wrapper {
  border: 1px solid rgba(255, 255, 255, 0.95) !important;
  box-shadow:
    0 0 0 3px rgba(255, 255, 255, 0.35),
    0 8px 18px rgba(30, 32, 40, 0.3) !important;
}
.is-listen-together .lt-avatar-wrapper {
  border-color: #ffffff !important;
}
.lt-duration-text {
  color: rgba(255, 255, 255, 0.62) !important;
  font-size: 12px !important;
  letter-spacing: 0.5px !important;
