/* =====================================================
   v5 重写：标题栏不再溢出 + 歌名/歌手真正写进 iPod 屏幕
   ---------------------------------------------------
   为什么 v4 不显示：歌名/歌手元素在 iPod 外面，
   写成 ".vinyl-disc .rp-song-title" 永远匹配不到。
   这版改成：iPod 和歌名/歌手都按「屏幕坐标」定位，
   位置关系由下面几个变量统一控制，想挪只改这里。
   ===================================================== */
:root {
  --ipod-top: 24vh;      /* iPod 顶部离屏幕顶部的距离（整体上下移动改这个）*/
  --stage-top: 234px;    /* ★ 舞台顶部离屏幕顶部的距离（按「一起听」显示时实测）。
                            iPod 在舞台里面，定位是从舞台顶部算起的，所以要减掉它。
                            iPod 跑得太靠下就调大，太靠上就调小 */
}

/* 让 iPod 所在层级低于歌名/歌手，避免文字被机身盖住 */
.rp-stage {
  position: relative !important;
  z-index: 0 !important;
}

/* iPod 钉在屏幕坐标里（水平居中），不再依赖原来的舞台布局 */
.vinyl-disc {
  position: fixed !important;
  top: calc(var(--ipod-top) - var(--stage-top)) !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;
  margin: 0 0 0 -104px !important;
  z-index: 0 !important;
}

/* ---------- 标题栏：整条用图片画，文字画在 SVG 里，永远不会溢出 ---------- */
.vinyl-disc::before,
.is-playing .vinyl-disc::before {
  content: "" !important;
  padding: 0 !important;
  overflow: hidden !important;
  white-space: nowrap !important;
  background-origin: border-box !important;
  background-repeat: no-repeat !important;
  background-size: 164px 17px, 100% 100% !important;
  background-position: 0 0, 0 0 !important;
}
/* 暂停：Pause + 蓝色暂停条 + 电池 */
.vinyl-disc::before {
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 164 17' preserveAspectRatio='xMinYMin meet'><text x='9' y='12' font-family='Helvetica Neue,Helvetica,Arial,sans-serif' font-size='9.5' font-weight='700' fill='%2314171c'>Pause</text><rect x='118' y='4.5' width='2.6' height='8' fill='%232a8bf2'/><rect x='122.4' y='4.5' width='2.6' height='8' fill='%232a8bf2'/><rect x='134' y='4.5' width='16' height='8' rx='1.6' fill='%2341c15a' stroke='%23666' stroke-width='.8'/><rect x='150.8' y='7' width='1.6' height='3' fill='%23666'/></svg>"),
    linear-gradient(180deg, #edf0f2 0, #cbd1d6 8px, #aeb5bc 16px, #8c939a 16px, #8c939a 17px, #ffffff 17px, #ffffff 100%) !important;
}
/* 播放：Now Playing + 蓝色播放三角 + 电池 */
.is-playing .vinyl-disc::before {
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 164 17' preserveAspectRatio='xMinYMin meet'><text x='9' y='12' font-family='Helvetica Neue,Helvetica,Arial,sans-serif' font-size='9.5' font-weight='700' fill='%2314171c'>Now Playing</text><path d='M118 4.5l7 4-7 4z' fill='%232a8bf2'/><rect x='134' y='4.5' width='16' height='8' rx='1.6' fill='%2341c15a' stroke='%23666' stroke-width='.8'/><rect x='150.8' y='7' width='1.6' height='3' fill='%23666'/></svg>"),
    linear-gradient(180deg, #edf0f2 0, #cbd1d6 8px, #aeb5bc 16px, #8c939a 16px, #8c939a 17px, #ffffff 17px, #ffffff 100%) !important;
}

/* ---------- 封面：屏幕左侧，Cover Flow 斜放 + 倒影 ---------- */
.vinyl-disc .circular-img {
  position: absolute !important;
  top: 48px !important;
  left: 15% !important;
  right: auto !important;
  bottom: auto !important;
  width: 62px !important;
  height: 66px !important;
  margin: 0 !important;
  transform: perspective(260px) rotateY(32deg) !important;
  transform-origin: 50% 50% !important;
  z-index: 6 !important;
}

/*⁣​‌⁠‌‌‌​​​‌‍‌​​⁠‍​‌⁠⁠​⁠⁠‌​⁠‍⁠​⁠​​‌⁠‍‌‍⁠​​⁠‍‍‍⁠‌‍‌⁠‌⁠​‍⁠‍⁠​​‍‌​​‍​⁣ ========================================================
   Apple Music 高仿真最终完美版
   ======================================================== */

:root {
    /* 1. 经典 Apple Music 尺寸比例 */
    --rp-disc-size: 350px;
    --rp-disc-radius: 20px;
    --rp-disc-bg: transparent;
    --rp-cover-size: 350px;
    --rp-cover-radius: 20px;

    /* 2. 细进度条 */
    --rp-scrubber-height: 7px;
    --rp-scrubber-radius: 999px;
    --rp-scrubber-bg: rgba(255, 255, 255, 0.18);
    --rp-scrubber-fill: rgba(255, 255, 255, 0.7);
    --rp-scrubber-thumb: transparent;
}

/* 3. 顶部横条 */
.rp-header {
    position: relative !important;
}
.rp-header::after {
    content: "" !important;
    position: absolute !important;
    top: 150px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    width: 56px !important;
    height: 4px !important;
    background: rgba(255, 255, 255, 0.4) !important;
    border-radius: 100px !important;
    pointer-events: none !important;
}

/* 4. 封面居中与上提 */
.rp-stage {
    margin-top: -200px !important;
    position: relative !important;
}
.vinyl-disc {
    position: relative !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    border: none !important;
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45) !important;
    animation: none !important;
    margin: 0 !important;
}
.circular-img { box-shadow: none !important; }
.tonearm-container { display: none !important; }
.lt-avatars-section { display: none !important; }

/* 5. 背景光晕氛围 + 隐藏页面切换小圆点 */
.bg-img {
    filter: blur(55px) saturate(160%) brightness(0.65) !important;
    transform: scale(1.2) !important;
}
.bg-overlay {
    background: radial-gradient(circle at 50% 30%, rgba(255,255,255,0.06) 0%, rgba(0,0,0,0.55) 100%) !important;
}
/* 彻底隐藏封面正下方的小圆点 */
.rp-dots, .rp-indicator, .swiper-pagination, .slick-dots,
div[class*="dot"], div[class*="indicator"], div[class*="pagination"] {
    display: none !important;
}

/* 6. 歌名与歌手（小箭头消失 + 播放条自然下移拉开间隙） */
.rp-song-title {
    font-size: 22px !important;
    font-weight: 700 !important;
    color: #ffffff !important;
}
.rp-song-artist {
    font-size: 16px !important;
    color: rgba(255, 255, 255, 0.55) !important;
    display: inline-block !important;
}
.rp-song-artist + *,
.rp-song-artist ~ svg,
.rp-song-artist::after {
    display: none !important;
}
.rp-now-playing, .rp-sleep, .rp-lyric { display: none !important; }

/* 播放条组件整体下移，撑开与歌手名的呼吸感 */
.scrubber-track, .rp-time-row {
    transform: translateY(18px) !important;
}

/* 7. 播放条与时间行稍微往上抬 */
.scrubber-track, .rp-time-row {
    transform: translateY(2px) !important;
}
.scrubber-track {
    margin-top: 0 !important;
}

/* 8. 右侧按钮：星星与三个点（加大加粗） */
.rp-btn-fav, .rp-btn-add {
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: 24px 24px !important;     /* 从 20px 放大到 24px */
    opacity: 0.9 !important;
}
.rp-btn-fav svg, .rp-btn-add svg, .rp-btn-share svg { opacity: 0 !important; }

/* 五角星：加粗加大 */
.rp-btn-fav {
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><polygon points='12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'/></svg>") !important;
}

/* 三个点：加大圆点尺寸 */
