/* ===== 滚动条美化 ===== */
.tm-story::-webkit-scrollbar { width: 3px !important; }
.tm-story::-webkit-scrollbar-thumb {
  background: rgba(126, 200, 227, 0.3) !important;
  border-radius: 3px !important;
}
.tm-story::-webkit-scrollbar-track {
  background: transparent !important;
}

/* ======= 修复 iOS 头像未占满 & 灰色边框问题 ======= */
.tm-top-drop-btn,
.tm-top-drop-btn-user {
  background: transparent !important; 
  -webkit-appearance: none !important; 
  box-sizing: border-box !important;
}
.tm-top-drop-btn img, 
.tm-top-drop-btn-user img {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  display: block !important;
  border-radius: 50% !important;
  transform: translateZ(0) !important; 
  -webkit-mask-image: -webkit-radial-gradient(white, black) !important; 
}
@supports (-webkit-touch-callout: none) {
  .tm-top-drop-btn img,
  .tm-top-drop-btn-user img {
    width: 100% !important;
    height: 100% !important;
    min-width: 100% !important;
    min-height: 100% !important;
  }
}

/* ==========================================================
   此时此刻 (This Moment) · 夜间黑 主题
   直接整段粘贴进「设定 → 画面美化 → 自定义 CSS」即可
   ========================================================== */

:root {
  --sns-bg: #1C1C1F;
  --sns-card-radius: 24px;
  --sns-text-main: #E4E1E6;
  --sns-text-sub: #9A979E;
  --sns-ring-color: #A78BC4;
  --sns-btn-bg: #26262B;
  --sns-accent-top: #35323C;
  --sns-accent-body: #2C2A31;
  --sns-input-bg: #232227;
  --sns-input-border: rgba(167,139,196,0.35);
  --sns-placeholder: #6E6B72;
  --sns-send-btn: #A78BC4;
}

/* ==========================================================
   全局背景 / 顶部导航栏（真实 DOM class）
   ========================================================== */
#this-moment-screen {
  background: #141416 !important;
}
.tm-bg-overlay {
  background: #1C1C1F !important;
}
.tm-header {
  background: var(--sns-btn-bg) !important;
  border-bottom: 1px solid var(--sns-input-border) !important;
}
.tm-header-name {
  color: var(--sns-text-main) !important;
}
.tm-btn-icon {
  color: var(--sns-text-main) !important;
}

/* ==========================================================
   输入区（真实 DOM class）
   ========================================================== */
.tm-compose {
  background: var(--sns-input-bg) !important;
  border-top: 1px solid var(--sns-input-border) !important;
}
.tm-compose-toolbar {
  background: transparent !important;
}
.tm-regen-btn,
.tm-suggestions-btn {
  color: var(--sns-text-sub) !important;
}
.tm-regen-btn.active {
  color: var(--sns-ring-color) !important;
}
.tm-compose-row {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}
.tm-input {
  background: var(--sns-input-bg) !important;
  color: var(--sns-text-main) !important;
  border: 1px solid var(--sns-input-border) !important;
  border-radius: 18px !important;
}
.tm-input::placeholder {
  color: var(--sns-placeholder) !important;
}
.tm-send-btn {
  background: var(--sns-send-btn) !important;
  color: #fff !important;
  border-radius: 50% !important;
}
.tm-suggestions-panel {
  background: var(--sns-btn-bg) !important;
  border: 1px solid var(--sns-input-border) !important;
}
.tm-suggestion-item {
  color: var(--sns-text-main) !important;
}
.tm-suggestion-direction {
  color: var(--sns-text-sub) !important;
}

/* ==========================================================
   1. AI 整体背景卡片 (强制居中)
   ========================================================== */
.tm-para-char {
  background: var(--sns-bg) !important;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35) !important;
  border-radius: var(--sns-card-radius) !important;
  padding: 16px 16px 72px 16px !important;
  border: none !important;
