}

.tc-avatar-img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 3px !important;
  filter: contrast(0.98) saturate(0.92) !important;
}

.tc-avatar-overlay {
  display: none !important;
}


